// 국적·영주 모의 평가 — 추가 문제(q061~q400) 몽골어 (질문 · 설명) ⚠️ 초안: 원어민 검수 필요
export const MOCK_MN_MORE: Record<string, { q: string; explain: string }> = {
  q061: { q: 'Тэгүкги далбааны голд байгаа тэгүк (태극) хээ юуг илэрхийлдэг вэ?', explain: 'Тэгүк хээ нь билиг (хөх) ба арга (улаан) хоёрын эв зохицлыг (음과 양의 조화) илэрхийлдэг.' },
  q062: { q: 'Тэгүкги далбааны дөрвөн гуа (4괘)-аас аль нь тэнгэрийг илэрхийлдэг вэ?', explain: 'Тэнгэрийг илэрхийлдэг нь гон гуа (건괘); 곤괘 нь газар, 감괘 нь ус, 리괘 нь гал юм.' },
  q063: { q: 'Тэгүкги далбааны дөрвөн гуагаас ли гуа (리괘) юуг илэрхийлдэг вэ?', explain: 'Ли гуа (리괘) нь галыг (불) илэрхийлдэг.' },
  q064: { q: 'Тэгүкги далбааны цагаан суурь юуг илэрхийлдэг вэ? Зөвийг нь сонгоно уу.', explain: 'Цагаан суурь нь гэгээ, ариун цайлган байдал, энх тайвныг эрхэмлэх сэтгэлийг (밝음과 순수, 평화를 사랑하는 마음) илэрхийлдэг.' },
  q065: { q: 'Дараахын аль өдөр Тэгүкги далбааг далбааны өргөний хэмжээгээр доошлуулж (гашуудлын байдлаар) мандуулдаг вэ?', explain: 'Эх орныхоо төлөө амиа өргөсөн хүмүүсийг дурсах Дурсгалын өдөр (현충일) далбааг доошлуулж мандуулдаг.' },
  q066: { q: 'Эх орныхоо төлөө амиа өргөсөн хүмүүсийг хүндэтгэн дурсах Дурсгалын өдөр (현충일) хэзээ вэ?', explain: 'Дурсгалын өдөр (현충일) нь 6 сарын 6 (6월 6일) бөгөөд амралтын өдөр юм.' },
  q067: { q: 'Дараахын аль нь улсын баярын өдөр (국경일) биш вэ?', explain: 'Улсын таван баярын өдөр нь 삼일절, 제헌절, 광복절, 개천절, 한글날 бөгөөд Хүүхдийн баяр (어린이날) амралтын өдөр боловч улсын баярын өдөр биш.' },
  q068: { q: 'Солонгост нийт хэдэн улсын баярын өдөр (국경일) байдаг вэ?', explain: 'Улсын баярын өдөр нийт 5 (5개): 삼일절, 제헌절, 광복절, 개천절, 한글날.' },
  q069: { q: 'Кэчонжол (개천절) хэдэн сарын хэдний өдөр вэ?', explain: 'Кочосоныг (고조선) үүсгэн байгуулсныг тэмдэглэдэг Кэчонжол нь 10 сарын 3 (10월 3일).' },
  q070: { q: '1919 онд болсон тусгаар тогтнолын төлөөх хөдөлгөөнийг тэмдэглэдэг улсын баярын өдөр аль вэ?', explain: '3 сарын 1-ний өдөр (삼일절) нь 1919 оны 3·1-ний хөдөлгөөнийг тэмдэглэдэг өдөр юм.' },
  q071: { q: 'Гванбокжол (광복절) хэдэн сарын хэдний өдөр вэ?', explain: 'Эх орноо эргүүлэн олсныг тэмдэглэдэг Гванбокжол нь 8 сарын 15 (8월 15일).' },
  q072: { q: 'Хангылын өдөр (한글날) юуг тэмдэглэдэг өдөр вэ?', explain: 'Хангылын өдөр нь Сэжон хаан Хунминжонъым үсгийг бүтээж, түгээн дэлгэрүүлсэн (훈민정음을 만들어 널리 알린 것) явдлыг тэмдэглэдэг.' },
  q073: { q: 'Төрийн чухал баримт бичигт дардаг, улсаа бэлгэдэх тамгыг юу гэдэг вэ?', explain: 'Улсыг бэлгэдэх тамга нь Төрийн тамга (국새) бөгөөд төрийн чухал баримт бичигт дардаг.' },
  q074: { q: 'Одоо хэрэглэж буй Төрийн тамганы (국새) бариулд сийлсэн домгийн шувуу аль вэ?', explain: 'Одоогийн Төрийн тамганы бариулд домгийн галт шувуу (봉황) сийлсэн байдаг.' },
  q075: { q: 'Бүгд Найрамдах Солонгос Улсын төрийн сүлдний (국장) голд ямар хээ зурсан байдаг вэ?', explain: 'Төрийн сүлд нь мүгунхва цэцгийн дэлбээн дунд тэгүк хээтэй (태극 문양), туузан дээрээ "대한민국" гэсэн бичигтэй.' },
  q076: { q: '"Мүгунхва" (무궁화) гэдэг нэр ямар утгатай вэ?', explain: 'Мүгунхва гэдэг нь "эцэс төгсгөлгүй дахин дахин цэцэглэдэг цэцэг" (끝없이 피고 또 피는 꽃) гэсэн утгатай.' },
  q077: { q: 'Мүгунхва цэцэг хэзээ цэцэглэдэг вэ? Зөвийг нь сонгоно уу.', explain: 'Мүгунхва цэцэг зунаас намар хүртэл буюу 7 сараас 10 сар хүртэл (7월부터 10월까지) удаан цэцэглэдэг.' },
  q078: { q: 'Эгукка (애국가) нийт хэдэн бадагтай вэ?', explain: 'Эгукка 4 бадагтай (4절) бөгөөд бадаг бүр ижил дахилттай.' },
  q079: { q: 'Эгукка-гийн дахилт "무궁화 삼천리 ( ) 강산"-ын хоосон зайд аль үг тохирох вэ?', explain: 'Дахилт нь "무궁화 삼천리 화려 강산" буюу "мүгунхва цэцэгт гурван мянган ли сайхан (화려) уул ус" гэж эхэлдэг.' },
  q080: { q: 'Одоо дуулж буй Эгукка-гийн аяыг хэн зохиосон бэ?', explain: 'Одоогийн Эгукка-гийн аяыг хөгжмийн зохиолч Ан Иктэ (안익태) зохиосон.' },
  q081: { q: 'Эгукка-гийн 2-р бадгийн "남산 위에 저 ( )" хэсэгт гардаг мод аль вэ?', explain: '2-р бадаг нь "남산 위에 저 소나무…" буюу "Намсан уулан дээрх нарс (소나무) төмөр хуяг өмссөн мэт" гэсэн үг.' },
  q082: { q: 'Энгийн хувцастай үедээ төрийн далбаанд хүндэтгэл үзүүлэхдээ баруун гараа хаана тавьдаг вэ?', explain: 'Далбаанд хүндэтгэл үзүүлэхдээ баруун гараа дэлгэж зүүн цээжин дээрээ (왼쪽 가슴) тавиад далбаа руу хардаг.' },
  q083: { q: 'Төрийн далбааны өмнө өргөх тангаргийн "( )롭고 정의로운 대한민국" хэсгийн хоосон зайд аль үг тохирох вэ?', explain: 'Тангарагт "자유롭고 정의로운 대한민국" буюу "эрх чөлөөтэй (자유), шударга Бүгд Найрамдах Солонгос Улс" гэсэн үг гардаг.' },
  q084: { q: 'Албан ёсны арга хэмжээний төрийн ёслолд (국민의례) хамгийн түрүүнд юу хийдэг вэ?', explain: 'Төрийн ёслол нь далбаанд хүндэтгэл үзүүлэх (국기에 대한 경례), төрийн дуулал дуулах, чимээгүй зогсож хүндэтгэл үзүүлэх гэсэн дарааллаар явагдана.' },
  q085: { q: '"Хунминжонъым" (훈민정음) гэдэг нэр ямар утгатай вэ?', explain: 'Хунминжонъым гэдэг нь "ард түмэнд заах зөв авиа" (백성을 가르치는 바른 소리) гэсэн утгатай.' },
  q086: { q: 'Сэжон хаан Хунминжонъымыг ард түмэнд хэдэн онд зарлан түгээсэн бэ?', explain: 'Хунминжонъымыг 1443 онд бүтээж, 1446 онд (1446년) зарлан түгээсэн.' },
  q087: { q: 'Хангыл үсгийг бүтээсэн зарчим, хэрэглэх аргыг тайлбарласан ном аль вэ?', explain: 'Хунминжонъым хэрэбон (훈민정음 해례본) нь Хангылын зарчмыг тайлбарласан ном бөгөөд 1997 онд ЮНЕСКО-гийн Дэлхийн баримтат өвд бүртгэгдсэн.' },
  q088: { q: 'Хангылын үндсэн гийгүүлэгч (ㄱ, ㄴ, ㅁ, ㅅ, ㅇ) үсгийг юуны хэлбэрийг дуурайж бүтээсэн бэ?', explain: 'Үндсэн гийгүүлэгчийг дуу гаргах үеийн ам, хэл, хоолойн хэлбэрийг (소리 낼 때의 입과 혀의 모양) дуурайж бүтээсэн.' },
  q089: { q: 'Хангылын үндсэн эгшиг "·, ㅡ, ㅣ"-г юуг дуурайж бүтээсэн бэ?', explain: 'Үндсэн эгшгүүд нь тэнгэр (·), газар (ㅡ), хүнийг (ㅣ) дуурайсан (하늘·땅·사람).' },
  q090: { q: 'Хунминжонъымыг анх бүтээхэд нийт хэдэн үсэгтэй байсан бэ?', explain: 'Анх 17 гийгүүлэгч, 11 эгшиг, нийт 28 үсэгтэй (28자) байсан бол одоо 24 үсэг хэрэглэдэг.' },
  q091: { q: 'Дараахын аль нь Бүгд Найрамдах Солонгос Улсын төрийн бэлгэдэл биш вэ?', explain: 'Солонгосын төрийн бэлгэдэл нь 태극기, 애국가, 무궁화, 국새, 국장 бөгөөд интоорын цэцэг (벚꽃) биш.' },
  q092: { q: 'Хангыл ямар төрлийн үсэг вэ?', explain: 'Хангыл бол авиа тэмдэглэдэг үсэг (소리를 적는 글자) юм.' },
  q093: { q: 'Үндсэн хуулийн дагуу Бүгд Найрамдах Солонгос Улсын бүрэн эрх хэнд байдаг вэ?', explain: 'Үндсэн хуулийн 1 дүгээр зүйлд бүрэн эрх ард түмэнд (국민) байх бөгөөд бүх эрх мэдэл ард түмнээс гарна гэж заасан.' },
  q094: { q: 'Үндсэн хуульд өөрчлөлт оруулахад парламент шийдвэрлэсний дараа заавал ямар журмаар явах ёстой вэ?', explain: 'Үндсэн хуулийн өөрчлөлтийн төслийг парламент баталсны дараа бүх нийтийн санал асуулгаар (국민 투표) дэмжигдсэн тохиолдолд эцэслэнэ.' },
  q095: { q: 'Ард түмэн улсынхаа эзэн болж, төрийн хэргийг шийддэг улс төрийн тогтолцоог юу гэдэг вэ?', explain: 'Ард түмэн эзэн нь болж улсаа удирддаг тогтолцоог ардчилал (민주주의) гэдэг.' },
  q096: { q: 'Ард түмэн сонгуулиар төлөөлөгчөө сонгож, тэр төлөөлөгч нь ард түмнийг төлөөлөн төрийн хэргийг эрхэлдэг тогтолцоо аль вэ?', explain: 'Төлөөлөгч сонгож төрийн хэргийг даатгадаг тогтолцоог төлөөллийн ардчилал (대의 민주 정치) гэдэг.' },
  q097: { q: 'Санал зөрөхөд илүү олон хүний дэмжсэн талаар шийддэг аргыг юу гэдэг вэ?', explain: 'Олонхын саналаар шийдэхийг олонхын зарчим (다수결의 원칙) гэдэг бөгөөд цөөнхийн саналыг ч хүндэтгэх ёстой.' },
  q098: { q: 'Төр ард түмний тогтоосон хуулийн дагуу улсаа удирдах ёстой гэсэн зарчмыг юу гэдэг вэ?', explain: 'Улсыг хуулийн дагуу удирдах зарчмыг хууль дээдлэх ёс (법치주의) гэдэг.' },
  q099: { q: 'Гүйцэтгэх засаглалын дээд удирдагч бөгөөд гадаад улсын өмнө улсаа төлөөлдөг хүн хэн бэ?', explain: 'Ерөнхийлөгч (대통령) нь гүйцэтгэх засаглалын тэргүүн бөгөөд гадаад улсын өмнө улсаа төлөөлдөг.' },
  q100: { q: 'Солонгост нэг хүн Ерөнхийлөгчөөр хэдэн удаа ажиллаж болох вэ? Зөвийг нь сонгоно уу.', explain: 'Ерөнхийлөгч 5 жилийн ганц бүрэн эрхийн хугацаатай тул зөвхөн нэг удаа (한 번만) ажиллана.' },
  q101: { q: 'Ерөнхийлөгчийн сонгуульд нэр дэвшихийн тулд хэдэн наснаас дээш байх ёстой вэ?', explain: 'Ерөнхийлөгчид нэр дэвшигч сонгуулийн өдрийн байдлаар 40 нас (만 40세) хүрсэн байх ёстой.' },
  q102: { q: 'Солонгосын Ерөнхийлөгчийг хэрхэн сонгодог вэ?', explain: 'Ерөнхийлөгчийг ард түмэн шууд санал өгч сонгодог (국민이 직접 투표로 뽑는다).' },
  q103: { q: 'Ерөнхийлөгч ямар нэг шалтгаанаар ажиллах боломжгүй болоход түүний бүрэн эрхийг хамгийн түрүүнд хэн орлон гүйцэтгэх вэ?', explain: 'Ерөнхийлөгч үүргээ гүйцэтгэх боломжгүй бол Ерөнхий сайд (국무총리) хамгийн түрүүнд түүний бүрэн эрхийг орлон гүйцэтгэнэ.' },
  q104: { q: 'Үндсэн хуулийн дагуу зэвсэгт хүчнийг удирдан захирдаг хүн хэн бэ?', explain: 'Үндсэн хуулийн дагуу Ерөнхийлөгч (대통령) зэвсэгт хүчнийг захирна.' },
  q105: { q: 'Парламентаар батлагдсан хуулийн төслийг Ерөнхийлөгч эсэргүүцэж, парламентаар дахин хэлэлцүүлэхийг шаардах эрхийг юу гэдэг вэ?', explain: 'Ерөнхийлөгч хуулийн төсөлд хориг тавих эрхээрээ (법률안 거부권) парламентаас дахин шийдвэрлэхийг шаардаж болно.' },
  q106: { q: 'Парламентын гишүүний бүрэн эрхийн хугацаа хэдэн жил вэ?', explain: 'Парламентын гишүүний бүрэн эрхийн хугацаа 4 жил (4년) бөгөөд дахин нэр дэвшиж болно.' },
  q107: { q: 'Парламентын сонгуульд намын авсан саналын хувиар сонгогддог гишүүнийг юу гэдэг вэ?', explain: 'Намын авсан саналын хувиар суудал хуваарилж сонгогддог гишүүнийг пропорциональ төлөөллийн гишүүн (비례대표 국회의원) гэдэг.' },
  q108: { q: 'Засгийн газрын боловсруулсан дараа жилийн улсын төсвийн төслийг хэлэлцэж баталдаг байгууллага аль вэ?', explain: 'Засгийн газар төсвийн төслөө өргөн барихад парламент (국회) хэлэлцэж баталдаг.' },
  q109: { q: 'Парламент жил бүр төрийн байгууллагууд ажлаа зөв хийж байгаа эсэхийг шалгахыг юу гэдэг вэ?', explain: 'Парламент төрийн үйл ажиллагааны хяналт шалгалтаар (국정 감사) Засгийн газрын ажлыг шалгадаг.' },
  q110: { q: 'Парламентыг төлөөлж, парламентын хуралдааныг удирддаг хүн хэн бэ?', explain: 'Парламентын дарга (국회의장) парламентыг төлөөлж, хуралдааныг удирддаг.' },
  q111: { q: 'Парламент Ерөнхийлөгчийг огцруулах саналыг баталсны дараа огцруулах эсэхийг эцэслэн шийддэг байгууллага аль вэ?', explain: 'Ерөнхийлөгчийг огцруулах эсэхийг Үндсэн хуулийн цэц (헌법재판소) хянан эцэслэн шийддэг.' },
  q112: { q: 'Ерөнхийлөгч Ерөнхий сайдыг томилохдоо аль байгууллагын зөвшөөрлийг авах ёстой вэ?', explain: 'Ерөнхийлөгч Ерөнхий сайдыг парламентын (국회) зөвшөөрлийг авсны дараа томилдог.' },
  q113: { q: 'Ерөнхийлөгчид туслаж, түүний тушаалаар яамдыг удирддаг хүн хэн бэ?', explain: 'Ерөнхий сайд (국무총리) Ерөнхийлөгчид туслаж, түүний тушаалаар яамдыг нэгтгэн удирддаг.' },
  q114: { q: 'Засгийн газрын чухал бодлогыг хэлэлцдэг Төрийн зөвлөлийн хуралдааны (국무회의) дарга хэн бэ?', explain: 'Төрийн зөвлөлийн хуралдааны дарга нь Ерөнхийлөгч (대통령), орлогч дарга нь Ерөнхий сайд.' },
  q115: { q: 'Цагаачдад зориулсан Нийгэмд нэгтгэх хөтөлбөрийг (KIIP) аль төв байгууллага хэрэгжүүлдэг вэ?', explain: 'Нийгэмд нэгтгэх хөтөлбөрийг хил нэвтрэлт, цагаачлалын асуудал хариуцдаг Хууль зүйн яам (법무부) хэрэгжүүлдэг.' },
  q116: { q: 'Улсын орлого, зарлагыг шалгаж, төрийн албан хаагчид ажлаа зөв хийж байгаа эсэхийг хянадаг байгууллага аль вэ?', explain: 'Төрийн аудит, хяналтын байгууллага (감사원) улсын санхүүг шалгаж, төрийн албан хаагчдын ажлыг хянадаг.' },
  q117: { q: 'Солонгосын хамгийн дээд шүүх аль вэ?', explain: 'Дээд шүүх (대법원) нь хамгийн дээд шатны шүүх бөгөөд голчлон гурав дахь шатны шүүх хуралдааныг хийдэг.' },
  q118: { q: 'Парламентын баталсан хууль Үндсэн хуульд нийцэж байгаа эсэхийг шийддэг байгууллага аль вэ?', explain: 'Хууль Үндсэн хуульд нийцэж буй эсэхийг Үндсэн хуулийн цэц (헌법재판소) хянан шийддэг.' },
  q119: { q: 'Үндсэн хуулийн цэц нийт хэдэн гишүүнтэй вэ?', explain: 'Үндсэн хуулийн цэц 9 гишүүнээс (9명) бүрддэг.' },
  q120: { q: 'Гэр бүл цуцлалт, гэр бүлийн харилцааны асуудлыг голчлон хянадаг шүүх аль вэ?', explain: 'Гэр бүл цуцлалт, эцэг эхийн эрх зэрэг гэр бүлийн асуудлыг голчлон Гэр бүлийн шүүх (가정 법원) хянадаг.' },
  q121: { q: 'Хүн бүр нэг нэг саналтай, санал бүр ижил үнэ цэнэтэй байх сонгуулийн зарчим аль вэ?', explain: 'Хүн бүр нэг саналтай, ижил үнэ цэнээр санал өгөхийг тэгш сонгууль (평등 선거) гэдэг.' },
  q122: { q: 'Тодорхой насанд хүрсэн хэн ч эд хөрөнгө, хүйс, боловсролоос үл хамааран санал өгч болох сонгуулийн зарчим аль вэ?', explain: 'Тодорхой насанд хүрсэн бүх иргэнд сонгох эрх олгохыг бүх нийтийн сонгууль (보통 선거) гэдэг.' },
  q123: { q: 'Дараахын аль нь ардчилсан сонгуулийн 4 үндсэн зарчмын нэг биш вэ?', explain: '4 зарчим нь 보통·평등·직접·비밀 선거 бөгөөд ил сонгууль (공개 선거) биш, учир нь саналаа нууцлах ёстой.' },
  q124: { q: 'Сонгууль болон бүх нийтийн санал асуулгыг шударга зохион байгуулах зорилгоор Үндсэн хуулийн дагуу байгуулсан байгууллага аль вэ?', explain: 'Сонгуулийн хороо (선거관리위원회) нь сонгууль, санал асуулгыг шударга зохион байгуулдаг Үндсэн хуулийн байгууллага юм.' },
  q125: { q: 'Сонгуулийн өдөр санал өгөх боломжгүй хүмүүс сонгуулийн өмнө урьдчилан санал өгдөг тогтолцоог юу гэдэг вэ?', explain: 'Урьдчилсан санал хураалт (사전 투표) нь сонгуулийн өмнө тогтоосон хоёр өдөр урьдчилан санал өгөх тогтолцоо юм.' },
  q126: { q: 'Санал авах байранд очиж санал өгөхдөө заавал юу авч явах ёстой вэ?', explain: 'Санал авах байранд иргэний үнэмлэхээр (신분증) биеэ баталгаажуулсны дараа саналын хуудас авдаг.' },
  q127: { q: 'Ерөнхийлөгчийн сонгууль эсвэл парламентын сонгуулийн өдөр ямар өдөр вэ?', explain: 'Ерөнхийлөгч болон парламентын сонгуулийн өдөр хүн бүр санал өгөх боломжтой байхаар амралтын өдөр (공휴일) байдаг.' },
  q128: { q: 'Хотын дарга, мужийн захирагч, орон нутгийн зөвлөлийн гишүүдийг сонгох орон нутгийн сонгуулийг хэдэн жил тутам явуулдаг вэ?', explain: 'Орон нутгийн сонгуулийг 4 жил тутам (4년) улс даяар нэгэн зэрэг явуулдаг.' },
  q129: { q: 'Байнгын оршин суух эрх авснаас хойш 3 жил өнгөрсөн, 18-аас дээш насны гадаад иргэн аль сонгуульд санал өгч болох вэ?', explain: 'Байнгын оршин суух эрх авснаас хойш 3 жил болсон гадаад иргэн оршин суугаа нутгийнхаа орон нутгийн сонгуульд (지방 선거) санал өгч болно.' },
  q130: { q: 'Ерөнхийлөгчийн сонгуульд санал өгөх эрхтэй хүн аль нь вэ? Зөвийг нь сонгоно уу.', explain: 'Ерөнхийлөгчийн сонгуульд зөвхөн 18-аас дээш насны Солонгосын иргэн (만 18세 이상 대한민국 국민) санал өгөх бөгөөд иргэншил авсан хүн ч үүнд хамаарна.' },
  q131: { q: 'Парламентын сонгуульд нэр дэвших нас хэдээс дээш вэ?', explain: '18-аас дээш насны (만 18세) иргэн парламентын сонгуульд нэр дэвшиж болно.' },
  q132: { q: 'Улс төрийн үзэл бодол нэгтэй хүмүүс засгийн эрх авах зорилгоор нэгдэн байгуулсан байгууллагыг юу гэдэг вэ?', explain: 'Засгийн эрх авах зорилгоор улс төрийн үзэл нэгтэй хүмүүсийн нэгдсэн байгууллагыг улс төрийн нам (정당) гэдэг.' },
  q133: { q: 'Сонгуулийн үеэр нэр дэвшигчээс мөнгө, бэлэг авах талаар аль нь зөв бэ?', explain: 'Нэр дэвшигчээс мөнгө, бэлэг авах нь хууль бус тул шийтгэл хүлээж болно (불법이므로 처벌받을 수 있다).' },
  q134: { q: 'Орон нутгийн оршин суугчид төлөөлөгчөө сонгож, тухайн нутгийн асуудлыг өөрсдөө шийддэг тогтолцоог юу гэдэг вэ?', explain: 'Оршин суугчид нутгийнхаа асуудлыг өөрсдөө шийдэж зохицуулахыг орон нутгийн өөрөө удирдах ёс (지방 자치 제도) гэдэг.' },
  q135: { q: 'Орон нутгийн журам гаргаж, орон нутгийн засаг захиргааны төсвийг хэлэлцдэг байгууллага аль вэ?', explain: 'Орон нутгийн зөвлөл (지방 의회) нь иргэдийн сонгосон гишүүд журам гаргаж, төсөв хэлэлцдэг газар юм.' },
  q136: { q: 'Орон нутгийн зөвлөлөөс хууль тогтоомжийн хүрээнд гаргадаг тухайн нутгийн дүрмийг юу гэдэг вэ?', explain: 'Орон нутгийн зөвлөлийн гаргадаг дүрмийг орон нутгийн журам (조례) гэдэг.' },
  q137: { q: '양평군, 가평군 зэрэг кун (군)-ий захиргааг хариуцдаг орон нутгийн удирдагчийг юу гэдэг вэ?', explain: 'Кун-ий захиргааг хариуцдаг удирдагч нь кунсу (군수) бөгөөд иргэд сонгуулиар сонгодог.' },
  q138: { q: 'Хот, мужийн боловсролыг хариуцдаг, иргэд сонгуулиар шууд сонгодог хүн хэн бэ?', explain: 'Хот, мужийн боловсролын даргыг (교육감) орон нутгийн сонгуулиар иргэд шууд сонгодог.' },
  q139: { q: 'Ажлаа буруу хийсэн орон нутгийн удирдагч эсвэл зөвлөлийн гишүүнийг иргэд санал хураалтаар огцруулж болох тогтолцоог юу гэдэг вэ?', explain: 'Иргэд санал хураалтаар орон нутгийн удирдагч, зөвлөлийн гишүүнийг огцруулах тогтолцоог иргэдийн эгүүлэн татах журам (주민 소환제) гэдэг.' },
  q140: { q: 'Дараахын аль нь дээд шатны өөрөө удирдах нэгж (광역 자치 단체) вэ?', explain: 'Тусгай хот, томоохон хот, муж, тухайлбал Сөүл тусгай хот (서울특별시) нь дээд шатны нэгж, харин 시·군·구 нь анхан шатны нэгж юм.' },
  q141: { q: 'Сонгуульд санал өгөх, нэр дэвших зэргээр улсын улс төрд оролцох эрхийг юу гэдэг вэ?', explain: 'Сонгох, сонгогдох эрх зэрэг улс төрд оролцох эрхийг улс төрийн эрх (참정권) гэдэг.' },
  q142: { q: 'Сонгуульд нэр дэвшиж, төлөөлөгчөөр сонгогдох эрхийг юу гэдэг вэ?', explain: 'Санал өгөх эрх нь 선거권, нэр дэвшиж сонгогдох эрх нь сонгогдох эрх (피선거권) юм.' },
  q143: { q: 'Солонгост санал өгөх талаарх зөв тайлбар аль нь вэ?', explain: 'Санал өгөх нь иргэний эрх тул санал өгөөгүй ч торгууль байхгүй (투표하지 않아도 벌금은 없다), гэхдээ оролцох нь зүйтэй.' },
  q144: { q: 'Солонгосын засаглалын хэлбэр ямар вэ?', explain: 'Солонгос бол ард түмний сонгосон Ерөнхийлөгч гүйцэтгэх засаглалыг удирддаг ерөнхийлөгчийн засаглалтай (대통령제) улс юм.' },
  q145: { q: 'Бүх иргэн хүйс, шашин, нийгмийн байдлаасаа болж ялгаварлан гадуурхагдахгүй байх эрх юу вэ?', explain: 'Хуулийн өмнө хэн ч ялгаварлагдахгүй байх эрх бол тэгш эрх (평등권) юм.' },
  q146: { q: 'Цэвэр, эрүүл орчинд амьдрах эрх юу вэ?', explain: 'Үндсэн хуульд бүх иргэн эрүүл, тав тухтай орчинд амьдрах эрхтэй гэж заасан бөгөөд үүнийг байгаль орчны эрх (환경권) гэнэ.' },
  q147: { q: 'Төрөөс хүний ёсоор амьдрах нөхцөлийг хангахыг шаардах эрх юу вэ?', explain: 'Боловсрол, хөдөлмөр, халамж зэрэг хүний ёсоор амьдрахыг шаардах эрх бол нийгмийн эрх (사회권) юм.' },
  q148: { q: 'Шашин шүтэх эсвэл шүтэхгүй байх эрх чөлөө нь ямар үндсэн эрхэд хамаарах вэ?', explain: 'Шашин шүтэх эрх чөлөө нь төрийн оролцоогүй байх эрх чөлөөний эрх (자유권)-д хамаарна.' },
  q149: { q: 'Эрх нь зөрчигдсөн үед төрөөс шүүхээр шийдвэрлүүлэх зэргийг шаардах эрх юу вэ?', explain: 'Шүүхэд хандах зэргээр төрөөс эрхээ сэргээлгэхийг шаардах эрхийг нэхэмжлэх эрх (청구권) гэнэ.' },
  q150: { q: 'Үндсэн хуульд бүх үндсэн эрхийн суурь болох үнэт зүйл юу вэ?', explain: 'Үндсэн хуулийн 10-р зүйлд бүх иргэн хүний нэр төр, үнэ цэнэ (인간의 존엄과 가치)-тэй гэж заасан.' },
  q151: { q: 'Иргэдийн үндсэн эрхийг зайлшгүй тохиолдолд хязгаарлахдаа юунд үндэслэх ёстой вэ?', explain: 'Үндсэн эрхийг үндэсний аюулгүй байдал, нийгмийн дэг журам, нийтийн сайн сайхны төлөө зайлшгүй үед зөвхөн хуулиар (법률) хязгаарлаж болно.' },
  q152: { q: 'Ялгаварлан гадуурхалт эсвэл хүний эрхийн зөрчилд өртвөл аль төрийн байгууллагад гомдол гаргаж болох вэ?', explain: 'Хүний эрх зөрчигдсөн эсвэл ялгаварлагдсан бол Үндэсний хүний эрхийн комисс (국가인권위원회)-т гомдол гаргаж болно.' },
  q153: { q: 'Үндсэн хуульд иргэний эрх бөгөөд нэгэн зэрэг үүрэг болох зүйл юу вэ?', explain: 'Боловсрол (교육) нь суралцах эрх бөгөөд хүүхдээ сургах үүрэг юм.' },
  q154: { q: 'Солонгос эрэгтэйчүүд тодорхой насанд хүрээд цэрэгт явдаг нь ямар үүргээс үүдэлтэй вэ?', explain: 'Эх орноо хамгаалахын тулд цэргийн алба хаах нь батлан хамгаалах үүрэг (국방의 의무) юм.' },
  q155: { q: 'Эцэг эх хүүхдээ бага болон дунд сургуульд сургах ёстой үүрэг юу вэ?', explain: 'Хүүхдээ заавал эзэмших боловсрол олгох нь боловсролын үүрэг (교육의 의무) юм.' },
  q156: { q: 'Солонгосын заавал эзэмших боловсрол нийт хэдэн жил вэ?', explain: 'Заавал эзэмших боловсрол нь бага сургууль 6, дунд сургууль 3, нийт 9 жил (9년).' },
  q157: { q: 'Хөдөлмөрлөх чадвартай иргэн шударгаар ажиллах ёстой үүрэг юу вэ?', explain: 'Үндсэн хуульд бүх иргэн хөдөлмөрлөх үүрэг (근로의 의무)-тэй гэж заасан.' },
  q158: { q: 'Дөрвөн үндсэн үүргээс гадна Үндсэн хуульд заасан иргэний үүрэг юу вэ?', explain: 'Үндсэн хуульд иргэд байгаль орчноо хамгаалахын төлөө хичээх үүрэг (환경 보전의 의무)-тэй гэж заасан.' },
  q159: { q: 'Солонгост ажиллаж орлого олдог гадаад иргэний татварын талаар зөв нь аль вэ?', explain: 'Солонгост орлоготой гадаад иргэн ч хуулийн дагуу Солонгост татвар төлнө (한국에 세금을 내야 한다).' },
  q160: { q: 'Солонгост гэрлэлтийг хуулиар хүлээн зөвшөөрүүлэхийн тулд юу хийх ёстой вэ?', explain: 'Хурим хийсэн ч гэрлэлтээ бүртгүүлсэн (혼인 신고) байж хуулийн дагуу эхнэр нөхөр болно.' },
  q161: { q: 'Солонгосын Иргэний хуулиар хэдэн настайд насанд хүрсэнд (том хүн) тооцогдох вэ?', explain: 'Солонгост бүтэн 19 нас (만 19세) хүрвэл насанд хүрсэнд тооцогдоно.' },
  q162: { q: 'Солонгост хүүхэд төрвөл төрсний бүртгэлийг хэдий хугацаанд хийх ёстой вэ?', explain: 'Төрсний бүртгэлийг хүүхэд төрснөөс хойш 1 сарын дотор (1개월 이내) хийх ёстой.' },
  q163: { q: 'Эхнэр нөхөр харилцан тохиролцож салахыг юу гэж нэрлэдэг вэ?', explain: 'Эхнэр нөхөр тохиролцож, шүүхээр баталгаажуулан салахыг харилцан тохиролцсон гэр бүл цуцлалт (협의 이혼) гэнэ.' },
  q164: { q: 'Гэрээслэлгүйгээр хуулийн дагуу өв залгамжлахад эхнэр/нөхөр нэг хүүхэдтэй харьцуулахад хэр их хувь авах вэ?', explain: 'Хуулийн дагуу өв залгамжлахад эхнэр/нөхөр хүүхдийн хувиас 1.5 дахин (1.5배를 받는다) их авна.' },
  q165: { q: 'Төрөлт, гэрлэлт, нас баралт зэрэг гэр бүлийн харилцааг бүртгэдэг албан ёсны бүртгэл юу вэ?', explain: '2008 оноос гэр бүлийн харилцааг 호적-ийн оронд гэр бүлийн харилцааны бүртгэл (가족관계등록부)-д тэмдэглэдэг.' },
  q166: { q: 'Гэр бүлийн хүчирхийллийн талаар зөв нь аль вэ?', explain: 'Гэр бүлийн хүчирхийлэл гэмт хэрэг тул 112 зэрэгт мэдэгдэж хамгаалалт авч болно (범죄이므로 신고할 수 있다).' },
  q167: { q: 'Дараахаас аль нь Үндсэн хуулиар баталгаажсан хөдөлмөрийн 3 эрхэд хамаарахгүй вэ?', explain: 'Хөдөлмөрийн 3 эрх нь эвлэлдэн нэгдэх, хамтын хэлэлцээр хийх, хамтын үйл ажиллагаа явуулах эрх бөгөөд сонгох эрх (선거권) биш.' },
  q168: { q: 'Хөдөлмөрийн стандартын хуульд долоо хоногийн үндсэн ажлын цагийг хэд гэж заасан бэ?', explain: 'Үндсэн ажлын цаг нь өдөрт 8, долоо хоногт 40 цаг (40시간).' },
  q169: { q: 'Долоо хоногт 15-аас дээш цаг ажиллаж, тогтоосон өдрүүдэд бүрэн ирвэл авах цалинтай амралтын өдрийн мөнгө юу вэ?', explain: 'Нөхцөлөө хангавал ажиллаагүй амралтын өдөр ч нэг өдрийн цалин буюу долоо хоногийн амралтын мөнгө (주휴 수당) авна.' },
  q170: { q: 'Нэг жилд 80-аас дээш хувийн ирцтэй ажилласан ажилтан хэдэн өдрийн цалинтай ээлжийн амралт авах вэ?', explain: 'Нэг жилд 80-аас дээш хувийн ирцтэй бол 15 өдрийн (15일) цалинтай ээлжийн амралт авна.' },
  q171: { q: 'Компани ажилласан цалинг өгөхгүй бол аль төрийн байгууллагад гомдол гаргаж болох вэ?', explain: 'Цалин өгөхгүй байгааг Хөдөлмөр эрхлэлт, хөдөлмөрийн яам (고용노동부)-нд мэдэгдэж болно.' },
  q172: { q: 'Ажлын байранд албан тушаал, харилцаагаа ашиглан бусад ажилтанд бие махбод, сэтгэл санааны зовлон учруулах талаар зөв нь аль вэ?', explain: 'Ажлын байран дахь дарамтыг Хөдөлмөрийн стандартын хуулиар хориглосон (법으로 금지되어 있다).' },
  q173: { q: 'Компани ажилтныг ажлаас халахын тулд хамгийн багадаа хэдэн өдрийн өмнө мэдэгдэх ёстой вэ?', explain: 'Ажлаас халахдаа 30 хоногийн (30일) өмнө мэдэгдэх эсвэл 30-аас доошгүй хоногийн цалин олгох ёстой.' },
  q174: { q: 'Нэг хүүхэд төрүүлэх эмэгтэй ажилтан төрөхийн өмнөх ба дараах амралтыг нийт хэдэн хоног авах вэ?', explain: 'Төрөхийн амралт 90 хоног (90일), ихэр бол 120 хоног.' },
  q175: { q: 'Өдөрт 8 цаг ажиллахад ажлын цагийн дунд хуулиар баталгаажсан завсарлага хэд вэ?', explain: '4 цаг ажиллавал 30-аас дээш минут, 8 цаг ажиллавал 1-ээс дээш цаг (1시간 이상) завсарлана.' },
  q176: { q: 'Гадаад ажилчдын хөдөлмөрийн хөлсний доод хэмжээний талаар зөв нь аль вэ?', explain: 'Хөдөлмөрийн хөлсний доод хэмжээ нь иргэншлээс үл хамааран бүх ажилчдад адилхан үйлчилнэ (한국인과 똑같이 적용된다).' },
  q177: { q: 'Бараа, үйлчилгээ худалдан аваад хохирол амсвал зөвлөгөө авах хэрэглэгчийн утасны дугаар хэд вэ?', explain: 'Хэрэглэгчийн хохирлын талаар 1372 хэрэглэгчийн зөвлөгөөний төвөөс зөвлөгөө авна.' },
  q178: { q: 'Дараахаас аль нь Хэрэглэгчийн тухай үндсэн хуулиар баталгаажсан хэрэглэгчийн эрх биш вэ?', explain: 'Хэрэглэгч аюулгүй байх, мэдээлэл авах, хохирлоо барагдуулах эрхтэй ч үнийг дураараа тогтоох эрхгүй (물건값을 마음대로 정할 권리).' },
  q179: { q: 'Гэрт ирсэн худалдагчаас бараа худалдан авбал гэрээ хүлээн авснаас хойш хэдэн өдрийн дотор худалдан авалтаа цуцалж болох вэ?', explain: 'Гэрээр худалдаалах замаар авсан барааг гэрээ хүлээн авснаас хойш 14 хоногийн (14일) дотор цуцалж болно.' },
  q180: { q: 'Хүнсний савлагаан дээрх тэмдэглэгээнээс аль нь идэхэд аюулгүй сүүлийн өдрийг заадаг вэ?', explain: '2023 оноос хүнсэнд идэж болох хугацаа буюу хэрэглэх хугацаа (소비기한)-г голчлон тэмдэглэдэг.' },
  q181: { q: 'Тамхи татахыг хориглосон бүсэд тамхи татвал яах вэ?', explain: 'Тамхи татахыг хориглосон бүсэд тамхи татвал торгууль төлнө (과태료를 낸다).' },
  q182: { q: 'Автомашинд суухдаа аль суудалд хамгаалах бүс зүүх ёстой вэ?', explain: '2018 оноос бүх замд бүх суудалд (모든 좌석) хамгаалах бүс зүүх нь заавал.' },
  q183: { q: 'Хүүхдийг хамгаалах бүс (сургуулийн бүс)-д автомашины үндсэн хурдны хязгаар хэд вэ?', explain: 'Хүүхдийг хамгаалах бүсэд ихэвчлэн цагт 30 км (시속 30km)-ээс хэтрүүлэхгүй явах ёстой.' },
  q184: { q: 'Цахилгаан скүүтер унахдаа хуулиар заавал мөрдөх зүйл юу вэ?', explain: 'Цахилгаан скүүтер унахад жолооны үнэмлэхтэй байж, хамгаалалтын малгай өмсөх ёстой (면허를 갖고 안전모를 쓴다).' },
  q185: { q: 'Гадаадад авсан олон улсын жолооны үнэмлэхээр Солонгост орж ирснээс хойш хэр удаан жолоодож болох вэ?', explain: 'Олон улсын жолооны үнэмлэх орж ирснээс хойш 1 жил (1년) хүчинтэй, дараа нь Солонгосын үнэмлэх хэрэгтэй.' },
  q186: { q: 'Солонгост марихуан (каннабис) татах талаар зөв нь аль вэ?', explain: 'Солонгост марихуан зэрэг мансууруулах бодис хууль бус бөгөөд хатуу шийтгэнэ (불법이며 처벌받는다).' },
  q187: { q: 'Амьдрал хүнд, өмгөөлөгч олоход бэрх хүмүүст үнэгүй хууль зүйн зөвлөгөө, нэхэмжлэлийн туслалцаа үзүүлдэг газар аль вэ?', explain: 'Солонгосын хууль зүйн туслалцааны корпораци (대한법률구조공단, 132) үнэгүй зөвлөгөө өгч, нэхэмжлэлд тусалдаг.' },
  q188: { q: 'Зээлүүлсэн мөнгөө буцааж авч чадаагүй учир шүүхэд хандан шийдвэрлүүлэх шүүх хурал аль вэ?', explain: 'Хувь хүмүүсийн хоорондын мөнгө, эд хөрөнгийн маргааныг иргэний хэргийн шүүх хурал (민사 재판)-аар шийднэ.' },
  q189: { q: 'Гадаад иргэн оршин суух хугацаа дууссаны дараа ч Солонгост үргэлжлүүлэн байхыг хүсвэл яах ёстой вэ?', explain: 'Хугацаа дуусахаас өмнө цагаачлалын байгууллагад оршин суух хугацаа сунгуулах хүсэлт гаргах ёстой (만료 전에 연장을 신청한다).' },
  q190: { q: 'Бүртгэлтэй гадаад иргэн нүүвэл шилжин ирснээс хойш хэдэн өдрийн дотор оршин суугаа газрын өөрчлөлтөө мэдэгдэх ёстой вэ?', explain: 'Нүүсэн гадаад иргэн шилжин ирснээс хойш 15 хоногийн (15일) дотор оршин суугаа газрын өөрчлөлтөө мэдэгдэнэ.' },
  q191: { q: 'Оюутан шиг гадаад иргэн оршин суух зөвшөөрлөөсөө өөр үйл ажиллагаа (жишээ нь цагийн ажил) эрхлэхийг хүсвэл яах ёстой вэ?', explain: 'Оршин суух зөвшөөрлөөс гадуурх үйл ажиллагаа эрхлэхдээ цагаачлалын байгууллагаас урьдчилан зөвшөөрөл авна (미리 허가를 받는다).' },
  q192: { q: 'Оршин суух хугацаа нь дууссан ч гарахгүй Солонгост үлдэхийг юу гэж нэрлэдэг вэ?', explain: 'Хууль бусаар оршин суух (불법 체류) нь торгууль, албадан гаргах, хил нэвтрэхийг хориглох зэрэг хариуцлагатай.' },
  q193: { q: 'Ерөнхий журмаар иргэний харьяалал авах хүсэлт гаргахын тулд зарчмын хувьд Солонгост хэдээс доошгүй жил тасралтгүй амьдрах ёстой вэ?', explain: 'Ерөнхий журмаар харьяалал авахад Солонгост 5-аас (5년) дээш жил тасралтгүй хаягтай байх ёстой.' },
  q194: { q: 'Солонгос хүнтэй гэрлэсэн гадаад иргэн гэрлэлттэй байдлаар Солонгост хэдээс дээш жил тасралтгүй амьдарвал хялбаршуулсан журмаар харьяалал хүсэх боломжтой вэ?', explain: 'Гэрлэлтийн цагаач гэрлэлттэй байдлаар Солонгост 2-оос (2년) дээш жил тасралтгүй амьдарвал хялбаршуулсан журмаар харьяалал хүсэж болно.' },
  q195: { q: '17-оос дээш насны гадаад иргэн Солонгост байнга биедээ юу авч явах ёстой вэ?', explain: '17-оос дээш насны гадаад иргэн гадаад паспорт эсвэл гадаад иргэний үнэмлэхээ (여권이나 외국인 등록증) биедээ авч явна.' },
  q196: { q: 'Гадаад иргэн хугацааны хязгааргүйгээр Солонгост үргэлжлүүлэн амьдрах боломжтой оршин суух зөвшөөрөл аль вэ?', explain: 'Байнга оршин суух (영주(F-5)) зөвшөөрөл авбал хугацааны хязгааргүй Солонгост амьдарч болно.' },
  q197: { q: 'Сургуулийн хүчирхийллийг мэдэгдэх эсвэл зөвлөгөө авах утасны дугаар хэд вэ?', explain: 'Сургуулийн хүчирхийллийг 117 дугаарт мэдэгдэж болно.' },
  q198: { q: 'Гэр бүлийн болон бэлгийн хүчирхийлэлд өртсөн хүн 24 цагаар зөвлөгөө авах эмэгтэйчүүдийн яаралтай утас хэд вэ?', explain: 'Эмэгтэйчүүдийн яаралтай утас 1366 хүчирхийллийн хохирогчдод 24 цагаар зөвлөгөө өгдөг.' },
  q199: { q: 'Барилга дотор байхад газар хөдөлж доргивол эхлээд юу хийх ёстой вэ?', explain: 'Доргиж байхад ширээн доор биеэ хамгаална (탁자 밑에서 몸을 보호한다), доргио зогсвол шатаар гарна.' },
  q200: { q: 'Барилгад гал гарахад гадагш зугтах зөв арга аль вэ?', explain: 'Гал гарахад цахилгаан шат зогсож болзошгүй тул шатаар (계단을 이용한다) зугтана.' },
  q201: { q: '119-д мэдэгдэхдээ хамгийн түрүүнд юуг үнэн зөв хэлэх ёстой вэ?', explain: 'Аврах баг хурдан ирэхийн тулд ослын газраа (사고가 난 장소) эхлээд зөв хэлнэ.' },
  q202: { q: 'Хорооны захиргааны ажлыг хариуцдаг захиргаа, халамжийн төв (행정복지센터)-ийг ихэвчлэн өөр ямар нэрээр нэрлэдэг вэ?', explain: '행정복지센터-ийг хуучин нэрээр нь иргэдийн төв (주민센터) эсвэл 동사무소 гэж бас нэрлэдэг.' },
  q203: { q: 'Гадаад иргэний бүртгэлд анх удаа хаана хүсэлт гаргадаг вэ?', explain: 'Гадаад иргэний бүртгэлийг амьдарч буй газрыг хариуцсан цагаачлалын алба (출입국·외국인사무소)-нд хүсэлт гаргана.' },
  q204: { q: 'Нүүсэн гадаад иргэн цагаачлалын албанаас гадна оршин суугаа газрын өөрчлөлтөө хаана мэдэгдэж болох вэ?', explain: 'Оршин суугаа газрын өөрчлөлтийг шинээр нүүсэн газрын захиргаа, халамжийн төв (행정복지센터)-д ч мэдэгдэж болно.' },
  q205: { q: 'Гадаад иргэд оршин суухтай холбоотой өргөдлөө онлайнаар гаргах, цагаачлалын албанд цаг захиалах төрийн цахим хуудас аль вэ?', explain: 'Оршин суухтай холбоотой өргөдөл гаргах, цаг захиалахыг HiKorea (하이코리아) хуудаснаас хийнэ.' },
  q206: { q: 'Оршин суугчийн бүртгэлийн хуулбар зэрэг албан бичгийг онлайнаар хүсэж, авах боломжтой төрийн цахим хуудас аль вэ?', explain: 'Оршин суугчийн бүртгэлийн хуулбар зэрэг олон бичгийг Засгийн газар 24 (정부24) хуудаснаас авна.' },
  q207: { q: 'Дараахаас аль нь 행정복지센터-д хийдэг ажил биш вэ?', explain: 'Оршин суух зөвшөөрлийн ангилал өөрчлөх зөвшөөрлийг (체류 자격 변경 허가) цагаачлалын албанаас авна.' },
  q208: { q: 'Ажилгүй гадаад иргэн зарчмын хувьд Солонгост хэдээс дээш сар байвал эрүүл мэндийн даатгалд заавал хамрагдах вэ?', explain: '6-аас (6개월) дээш сар оршин суусан гадаад иргэн орон нутгийн даатгуулагчаар эрүүл мэндийн даатгалд заавал хамрагдана.' },
  q209: { q: 'Их сургуулийн эмнэлэг зэрэг дээд шатлалын эмнэлэгт эрүүл мэндийн даатгалын хөнгөлөлт эдлэхэд ихэвчлэн юу хэрэгтэй вэ?', explain: 'Яаралтай биш бол ойрын эмнэлгээс авсан илгээх бичиг (진료 의뢰서) хэрэгтэй.' },
  q210: { q: 'Дархлаажуулалт, эрүүл мэндийн үзлэг зэрэг нийтийн эрүүл мэндийн үйлчилгээг хямд авах газар аль вэ?', explain: 'Дүүрэг бүрт байдаг эрүүл мэндийн төв (보건소)-өөс дархлаажуулалт зэрэг үйлчилгээ авна.' },
  q211: { q: 'Эмнэлгээс авсан жороор эм худалдаж авдаг газар аль вэ?', explain: 'Жортой эмийг эмийн сан (약국)-д жороо өгч худалдаж авна.' },
  q212: { q: 'Зүү, ургамлын эм зэрэг Солонгосын уламжлалт анагаах ухаанаар эмчилдэг эмнэлгийг юу гэдэг вэ?', explain: 'Уламжлалт анагаахын эмнэлэг (한의원)-т зүү, төөнүүр, ургамлын эмээр эмчлүүлж болно.' },
  q213: { q: 'Эрүүл мэндийн даатгалын шимтгэлээ удаан төлөөгүй гадаад иргэнд юу тохиолдож болох вэ?', explain: 'Эрүүл мэндийн даатгалын шимтгэл өрсөн бол оршин суух хугацаа сунгуулахад хүндрэл гарч болно (체류 기간 연장이 제한될 수 있다).' },
  q214: { q: 'Энгийн хог хаяхдаа ямар уут хэрэглэх ёстой вэ?', explain: 'Энгийн хогийг тухайн нутагт зардаг хэмжээгээр төлбөр төлөх уут (종량제 봉투)-нд хийж хаяна.' },
  q215: { q: 'Дараахаас алийг нь хүнсний хаягдалд хаяж болохгүй вэ?', explain: 'Тахианы яс (닭 뼈), хясаа зэрэг хатуу зүйлийг энгийн хогт хаяна.' },
  q216: { q: 'Ор, буйдан зэрэг том тавилга хаяхдаа яах вэ?', explain: 'Том тавилгыг том оврын хог гэж мэдэгдэж (대형 폐기물로 신고한다), хураамж төлж хаяна.' },
  q217: { q: '종량제 уут хэрэглэхгүйгээр хогоо нууцаар хаявал яах вэ?', explain: 'Хогоо нууцаар хаявал торгууль төлж магадгүй (과태료를 낼 수 있다).' },
  q218: { q: 'Тунгалаг усны савыг ангилж хаях зөв арга юу вэ?', explain: 'Тунгалаг PET савыг хоосолж, шошгыг нь салгаад тусад нь цуглуулж хаяна (라벨을 떼고 따로 모아 버린다).' },
  q219: { q: 'Барьцаа мөнгө өгч, сар бүр түрээсийн төлбөр төлж амьдардаг хэлбэрийг юу гэдэг вэ?', explain: 'Вөлсэ (월세) нь барьцаа өгч, сар бүр түрээс төлдөг хэлбэр юм.' },
  q220: { q: 'Түрээслэгч барьцаа мөнгөө хамгаалахын тулд шилжин ирэх бүртгэлтэй хамт түрээсийн гэрээндээ юу авах ёстой вэ?', explain: 'Шилжин ирснээ бүртгүүлж, баталгаажуулсан огноо (확정일자) авсан бол барьцаа мөнгөө тэргүүн ээлжинд буцаан авах эрх үүснэ.' },
  q221: { q: 'Байрны гэрээ хийхээс өмнө жинхэнэ эзэн болон байранд холбогдох өрийг шалгахын тулд ямар баримт үздэг вэ?', explain: 'Үл хөдлөх хөрөнгийн бүртгэлийн хуулбар (등기부등본)-аас эзэн болон барьцааны зээлийг мэдэж болно.' },
  q222: { q: 'Байр хайхад байрны эзэн ба түрээслэгчийн хооронд гэрээ хийхэд тусалдаг мэргэжилтэн хэн бэ?', explain: 'Үл хөдлөх хөрөнгийн тусгай зөвшөөрөлтэй зуучлагч (공인 중개사) худалдаа, түрээсийн гэрээг зуучилдаг.' },
  q223: { q: 'Орон сууцны түрээсийг хамгаалах хуулиар түрээслэгчид баталгаажуулсан гэрээний хамгийн бага хугацаа хэдэн жил вэ?', explain: 'Гэрээг 2 жилээс богино хугацаагаар хийсэн ч түрээслэгч 2 жил (2년) амьдарч болно.' },
  q224: { q: 'Автобуснаас буухдаа ч тээврийн картаа уншуулдаг шалтгаан юу вэ?', explain: 'Буухдаа картаа уншуулсан тохиолдолд өөр автобус, метронд шилжихэд хөнгөлөлт авна (환승 할인을 받기 위해).' },
  q225: { q: 'Метроны ягаан өнгийн тусгай суудал хэнд зориулагдсан бэ?', explain: 'Ягаан суудал нь жирэмсэн эмэгтэйчүүдэд (임산부) зориулж сул үлдээдэг суудал юм.' },
  q226: { q: 'Гадаад иргэн банкинд данс нээхэд ихэвчлэн ямар үнэмлэх хэрэгтэй вэ?', explain: 'Гадаад иргэд ихэвчлэн гадаад иргэний үнэмлэх (외국인 등록증) эсвэл паспортоор данс нээдэг.' },
  q227: { q: 'Өөрийн дансны дэвтэр эсвэл дебит картаа бусдад зээлдүүлэх, худалдах талаар зөв нь аль вэ?', explain: 'Банкны дансаа зээлдүүлэх, худалдах нь гэмт хэрэгт ашиглагдаж болох тул хууль бус бөгөөд шийтгэгдэнэ (불법이라 처벌받을 수 있다).' },
  q228: { q: 'Банкны касс хаагдсаны дараа ч мөнгө авах, хийх боломжтой машин юу вэ?', explain: 'ATM (현금 자동 입출금기)-ээр банкны касс хаагдсан ч мөнгө авч, хийж болно.' },
  q229: { q: 'Гадаад иргэд оршин суух болон визний асуудлаар олон хэлээр зөвлөгөө авах Гадаадын иргэдийн мэдээллийн төвийн дугаар хэд вэ?', explain: 'Оршин суух, визний талаар 1345 Гадаадын иргэдийн мэдээллийн төвөөс олон хэлээр зөвлөгөө авна.' },
  q230: { q: 'Гадаад хэлээр аялал жуулчлалын мэдээлэл, орчуулгын тусламж авах утасны дугаар хэд вэ?', explain: '1330 утас гадаад хэлээр аялал жуулчлалын мэдээлэл өгч, орчуулгад тусалдаг.' },
  q231: { q: 'Гэрлэлтийн цагаач болон олон соёлт гэр бүлүүд олон хэлээр амьдралын зөвлөгөө авдаг Дануры (다누리) дуудлагын төвийн дугаар хэд вэ?', explain: 'Дануры дуудлагын төв (1577-1366) олон соёлт гэр бүлүүдэд олон хэлээр зөвлөгөө өгдөг.' },
  q232: { q: 'Төрийн үйлчилгээний талаар хаанаас асуухаа мэдэхгүй үед зөвлөгөө авах Засгийн газрын иргэдийн дуудлагын төвийн дугаар хэд вэ?', explain: 'Засгийн газрын иргэдийн дуудлагын төв 110 олон байгууллагын үйлчилгээний талаар зөвлөгөө өгдөг.' },
  q233: { q: 'Солонгосын түүхэнд анх байгуулагдсан улс аль вэ?', explain: 'Солонгосын анхны улс бол Дангун Вангомын байгуулсан Гожусон (고조선) юм.' },
  q234: { q: 'Дангуны домогт шарилж, сармис идэж тэвчээд хүн болсон амьтан юу вэ?', explain: 'Баавгай (곰) шарилж, сармис идэж тэвчээд Унньё хэмээх эмэгтэй болсон.' },
  q235: { q: '"Хүн төрөлхтөнд өргөн тусыг үзүүл" гэсэн утгатай, Гожусоныг байгуулсан үзэл санаа юу вэ?', explain: 'Хунъик инган (홍익인간) нь "хүн төрөлхтөнд өргөн тусыг үзүүл" гэсэн утгатай бөгөөд одоо ч Солонгосын боловсролын үндсэн үзэл санаа хэвээр байна.' },
  q236: { q: 'Гожусон нийгмийн дэг журмыг сахиулахын тулд гаргасан хууль юу вэ?', explain: 'Гожусонд 8 зүйлт хууль (8조법) байсан бөгөөд үүнээс 3 зүйл нь өнөөг хүртэл уламжлагдан иржээ.' },
  q237: { q: 'Гогурёг байгуулсан хүн хэн бэ?', explain: 'Гогурёг Жумон (주몽) буюу Дунмён ван байгуулсан.' },
  q238: { q: 'Бэгжэг байгуулсан хүн хэн бэ?', explain: 'Бэгжэг Жумоны хүү Онжо (온조) Ханган мөрний сав газарт байгуулсан.' },
  q239: { q: 'Гогурёгийн нутаг дэвсгэрийг ихээр тэлсэн, хүүгийнх нь босгосон том хөшөө чулуу үлдсэн ван хэн бэ?', explain: 'Гуангэтхо их ван (광개토대왕) Гогурёгийн нутгийг тэлсэн бөгөөд хүү Жансу ван нь түүнд зориулан хөшөө чулуу босгосон.' },
  q240: { q: 'Гогурё, Бэгжэ, Шилла гурвын аль нь Гурван улсыг нэгтгэсэн бэ?', explain: 'Шилла (신라) 676 онд Гурван улсыг нэгтгэсэн.' },
  q241: { q: 'Шилла Гурван улсыг нэгтгэхэд их гавьяа байгуулсан жанжин хэн бэ?', explain: 'Жанжин Ким Юшин (김유신) Шиллагийн Гурван улсыг нэгтгэхэд чухал үүрэг гүйцэтгэсэн.' },
  q242: { q: 'Гогурёгийн жанжин Ыльжи Мундог Суй улсын цэргийг бут цохисон тулалдаан аль вэ?', explain: 'Ыльжи Мундог 612 онд Сальсугийн их тулалдаанд (살수 대첩) Суй улсын цэргийг бут цохисон.' },
  q243: { q: 'Нагдун мөрний доод хэсэгт олон төмөр үйлдвэрлэж, гадагш гаргадаг байсан холбооны вант улс аль вэ?', explain: 'Гая (가야) чанартай төмөр үйлдвэрлэж, хөрш орнууддаа гаргадаг байв.' },
  q244: { q: 'Гогурё гаралтай Тэ Жоён 698 онд байгуулсан улс аль вэ?', explain: 'Тэ Жоён Гогурёг залгамжлан 698 онд Бохай (발해) улсыг байгуулсан.' },
  q245: { q: 'Нэгдсэн Шилла өмнөд хэсэгт, Бохай хойд хэсэгт зэрэг оршиж байсан үеийг юу гэж нэрлэдэг вэ?', explain: 'Өмнөд хэсэгт Нэгдсэн Шилла, хойд хэсэгт Бохай зэрэг оршиж байсан үеийг Өмнөд, хойд улсын үе (남북국 시대) гэдэг.' },
  q246: { q: 'Нэгдсэн Шиллагийн үед Чонхэжин боомтыг байгуулж, далайн худалдааг удирдсан хүн хэн бэ?', explain: 'Жан Бого (장보고) Вандо аралд Чонхэжиныг байгуулж, далайн худалдааг удирдсан.' },
  q247: { q: 'Нэгдсэн Шиллагийн үед Гёнжү хотын Тохам ууланд чулуугаар барьсан агуйн сүм юу вэ?', explain: 'Сокгурам (석굴암) нь Нэгдсэн Шиллагийн үеийн агуйн сүм бөгөөд Пульгугса сүмийн хамт ЮНЕСКО-гийн Дэлхийн өвд бүртгэгдсэн.' },
  q248: { q: '918 онд Горёг байгуулсан хүн хэн бэ?', explain: 'Ван Гон (왕건) 918 онд Горёг байгуулж, Хожуу Гурван улсыг нэгтгэсэн.' },
  q249: { q: 'Англи хэл дээрх \'Korea\' гэдэг нэр аль улсын нэрээс гаралтай вэ?', explain: 'Горё (고려) улсын үеийн идэвхтэй худалдааны ачаар энэ нэр барууны орнуудад танигдаж \'Korea\' болсон.' },
  q250: { q: 'Горёгийн үед Монголын довтолгоог Буддын шашны хүчээр даван туулах зорилгоор бүтээж, Хэинса сүмд хадгалж буй зүйл юу вэ?', explain: 'Палман Тэжангён (팔만대장경) нь 80,000 гаруй модон хавтанд сийлсэн судар бөгөөд Хэинса сүмд хадгалагддаг.' },
  q251: { q: 'Одоо хадгалагдаж буй металл үсгээр хэвлэсэн номуудаас дэлхийд хамгийн эртний Горёгийн ном аль вэ?', explain: '1377 онд металл үсгээр хэвлэсэн Жикжи (직지심체요절) нь ЮНЕСКО-гийн Дэлхийн баримтат өвд бүртгэгдсэн.' },
  q252: { q: 'Горёгийн үед лам Ирён бичсэн, Дангуны домог багтсан түүхийн ном аль вэ?', explain: 'Ирёны бичсэн "Самгук юса" (삼국유사) номонд Дангуны домог багтсан.' },
  q253: { q: 'Горёгийн үед Гүйжүд Кидан улсын цэргийг бут цохисон жанжин хэн бэ?', explain: 'Ган Гамчан (강감찬) 1019 онд Гүйжүгийн их тулалдаанд Киданы цэргийг бут цохисон.' },
  q254: { q: '1392 онд Жусоныг байгуулсан хүн хэн бэ?', explain: 'И Сонгэ (이성계) буюу Тэжо ван 1392 онд Жусоныг байгуулсан.' },
  q255: { q: 'Жусоны нийслэл буюу одоогийн Сөүл хотыг тэр үед юу гэж нэрлэдэг байсан бэ?', explain: 'Жусон улс Ханьяныг (한양), өөрөөр хэлбэл одоогийн Сөүлийг нийслэлээ болгосон.' },
  q256: { q: 'Сэжун их ван Хунминжоныг бүтээсэн шалтгаан аль вэ?', explain: 'Сэжун ван хятад үсэг мэддэггүй ард түмэн амархан сурч бичих боломжтой болгохын тулд хялбар үсгийг бүтээсэн (백성이 쉽게 배워 쓰게 하려고).' },
  q257: { q: '1597 онд жанжин И Сүншин Улдолмог хоолойд цөөн хөлгөөр Японы олон хөлгийг ялсан тэнгисийн тулалдаан аль вэ?', explain: 'И Сүншин 1597 онд Мённяны тэнгисийн тулалдаанд (명량 해전) цөөн хөлгөөр хамаагүй олон Японы тэнгисийн цэргийг ялсан.' },
  q258: { q: 'Сэжуны үед шилдэг эрдэмтэд цуглан эрдэм шинжилгээ хийдэг байсан байгууллага аль вэ?', explain: 'Сэжун Жибхёнжоныг (집현전) хөгжүүлж, эрдэмтдийг эрдэм шинжилгээ хийлгэсэн.' },
  q259: { q: 'Сэжуны үед хур тунадасны хэмжээг хэмжих зорилгоор хийсэн багаж юу вэ?', explain: 'Чигүги (측우기) бол хур тунадас хэмжих багаж бөгөөд Сэжуны үед хийгдсэн.' },
  q260: { q: '1592 онд Япон Жусон руу довтолсноор эхэлсэн дайн юу вэ?', explain: 'Имжин дайн (임진왜란) 1592 онд Японы довтолгооноор эхэлж, 7 жил үргэлжилсэн.' },
  q261: { q: '1592 онд жанжин И Сүншин "тогоруун далавч" (학익진) байрлалаар Японы тэнгисийн цэргийг бут цохисон тулалдаан аль вэ?', explain: 'И Сүншин Хансандогийн их тулалдаанд (한산도 대첩) Японы тэнгисийн цэргийг ялсан.' },
  q262: { q: 'Жанжин И Сүншин Имжин дайны үеэр өөрөө бичсэн өдрийн тэмдэглэл юу вэ?', explain: '"Нанжүн илги" (난중일기) бол И Сүншиний дайны үеийн өдрийн тэмдэглэл бөгөөд ЮНЕСКО-гийн Дэлхийн баримтат өвд бүртгэгдсэн.' },
  q263: { q: 'Япон Их Хан эзэнт гүрний (대한제국) бүрэн эрхийг хүчээр булаан авсан нь хэдэн он бэ?', explain: '1910 онд (1910년) Япон Их Хан эзэнт гүрнийг хүчээр нэгтгэж, колоничлолоо эхлүүлсэн.' },
  q264: { q: '3·1-ний хөдөлгөөний дараа 1919 онд Хятадын Шанхай хотод байгуулсан засгийн газар юу вэ?', explain: '1919 онд Шанхайд Бүгд Найрамдах Солонгос Улсын Түр засгийн газар (대한민국 임시 정부) байгуулагдаж, тусгаар тогтнолын хөдөлгөөнийг удирдсан.' },
  q265: { q: 'Түр засгийн газрыг удирдаж, 『백범일지』 номыг бичсэн тусгаар тогтнолын тэмцэгч хэн бэ?', explain: 'Бэгбом хэмээн алдаршсан Ким Гу (김구) Түр засгийн газрыг удирдсан тэмцэгч бөгөөд 『백범일지』 номыг үлдээсэн.' },
  q266: { q: '3·1-ний хөдөлгөөний үеэр Чонан хотын Аунэ захад "Мансэ" хашхираан жагсаалыг удирдсан сурагч тэмцэгч хэн бэ?', explain: 'Ю Гвансүн (유관순) Аунэ захын жагсаалыг удирдаж, шоронд нас барсан.' },
  q267: { q: '1909 онд Хятадын Харбин хотод Ито Хиробумиг буудсан тусгаар тогтнолын тэмцэгч хэн бэ?', explain: 'Ан Жүнгын (안중근) 1909 онд Харбины галт тэрэгний буудалд Ито Хиробумиг буудсан.' },
  q268: { q: '3·1-ний хөдөлгөөний үеэр үндэстний 33 төлөөлөгчийн зарласан баримт бичиг юу вэ?', explain: 'Үндэстний 33 төлөөлөгч Тусгаар тогтнолын тунхаглал (독립 선언서) зарлаж, Солонгосын тусгаар тогтнолыг дэлхийд мэдэгдсэн.' },
  q269: { q: '1920 онд жанжин Ким Жважиний удирдсан тусгаар тогтнолын арми Манжуурт Японы цэргийг бут цохисон тулалдаан аль вэ?', explain: '1920 онд тусгаар тогтнолын арми Чонсаньригийн их тулалдаанд (청산리 대첩) Японы цэргийг ялсан.' },
  q270: { q: 'Бүгд Найрамдах Солонгос Улсын засгийн газар хэзээ байгуулагдсан бэ?', explain: 'Бүгд Найрамдах Солонгос Улсын засгийн газар 1948 оны 8-р сарын 15-нд (1948년 8월 15일) байгуулагдсан.' },
  q271: { q: 'Бүгд Найрамдах Солонгос Улсын анхны ерөнхийлөгч хэн бэ?', explain: '1948 онд И Сынман (이승만) Солонгосын анхны ерөнхийлөгч болсон.' },
  q272: { q: '1948 оны 5-р сарын 10-ны бүх нийтийн сонгуулиар бүрдэж, Үндсэн хуулийг баталсан парламентыг юу гэж нэрлэдэг вэ?', explain: '5-р сарын 10-ны сонгуулиар сонгогдсон Үндсэн хууль тогтоох их хурал (제헌 국회) 1948 онд Үндсэн хуулийг баталсан.' },
  q273: { q: 'Чөлөөлөгдсөний дараахан АНУ, ЗХУ Солонгосын хойгийг хойд, өмнөд хэсэгт хувааж захирсан шугам юу вэ?', explain: 'Чөлөөлөгдсөний дараа хойд өргөргийн 38-р параллелийг (38도선) хил болгон өмнөд хэсгийг АНУ, хойд хэсгийг ЗХУ захирсан.' },
  q274: { q: '6·25-ны дайны гал зогсоох хэлэлцээрт хэдэн онд гарын үсэг зурсан бэ?', explain: '1953 оны 7-р сарын 27-нд (1953년) гал зогсоох хэлэлцээрт гарын үсэг зурж, тулалдаан зогссон.' },
  q275: { q: '1950 оны 9-р сард НҮБ-ын цэрэг 6·25-ны дайны явцыг өөрчилсөн ажиллагаа юу вэ?', explain: '1950 оны 9-р сарын 15-ны Инчоны газардах ажиллагаагаар (인천 상륙 작전) Солонгосын арми болон НҮБ-ын цэрэг Сөүлийг эргүүлэн авсан.' },
  q276: { q: '6·25-ны дайны гал зогсоох хэлэлцээрт хаана гарын үсэг зурсан бэ?', explain: 'Гал зогсоох хэлэлцээрт 1953 онд Пханмунжомд (판문점) гарын үсэг зурсан.' },
  q277: { q: '6·25-ны дайн болон хойд, өмнөд хуваагдлаас болж хоорондоо салж, сураггүй амьдарч буй гэр бүлийг юу гэдэг вэ?', explain: 'Дайн, хуваагдлаас болж салсан гэр бүлийг салсан гэр бүл (이산가족) гэдэг бөгөөд хойд, өмнөд хоёр тэдэнд зориулсан уулзалт зохион байгуулж байсан.' },
  q278: { q: '1960 оны 3-р сарын 15-ны луйвартай сонгуулийг эсэргүүцэн оюутнууд, иргэдийн өрнүүлсэн ардчилсан хувьсгал юу вэ?', explain: '4-р сарын 19-ний хувьсгалын (4·19 혁명) үр дүнд ерөнхийлөгч И Сынман огцорсон.' },
  q279: { q: '1980 оны 5-р сард Гуанжү хотын иргэд цэргийн дарангуйллыг эсэргүүцэн өрнүүлсэн ардчиллын хөдөлгөөн юу вэ?', explain: '5-р сарын 18-ны ардчиллын хөдөлгөөн (5·18 민주화 운동) 1980 онд Гуанжүд өрнөсөн бөгөөд түүний баримтууд ЮНЕСКО-гийн Дэлхийн баримтат өвд бүртгэгдсэн.' },
  q280: { q: '1987 оны 6-р сард улс даяарх иргэд ерөнхийлөгчийг шууд сонгохыг шаардан өрнүүлсэн ардчиллын хөдөлгөөн юу вэ?', explain: '6-р сарын ардчиллын тэмцлийн (6월 민주 항쟁) үр дүнд ард түмэн ерөнхийлөгчөө шууд сонгох болсон.' },
  q281: { q: '2000 онд Өмнөд, Хойд Солонгосын удирдагчид анх удаа уулзаж, хэлэлцээ хийсэн хот аль вэ?', explain: '2000 оны 6-р сард Пхеньянд (평양) Өмнөд, Хойд Солонгосын анхны дээд хэмжээний уулзалт болж, 6·15-ны хамтарсан тунхаглал гарсан.' },
  q282: { q: '1960-1970-аад онд Солонгос гадаад валют олохын тулд уурхайчин, сувилагчдаа аль улс руу илгээсэн бэ?', explain: 'Баруун Германд (서독) ажилласан уурхайчин, сувилагчдын илгээсэн мөнгө Солонгосын эдийн засгийн хөгжилд тус болсон.' },
  q283: { q: '1970 онд ашиглалтад орсон, Сөүл, Пусан хотыг холбосон хурдны зам аль вэ?', explain: '1970 онд ашиглалтад орсон Гёнбу хурдны зам (경부 고속도로) аж үйлдвэржилт, эдийн засгийн өсөлтөд их үүрэг гүйцэтгэсэн.' },
  q284: { q: 'Солонгосчуудаас анх удаа Нобелийн энх тайвны шагнал хүртсэн ерөнхийлөгч хэн бэ?', explain: 'Ерөнхийлөгч Ким Дэжүн (김대중) ардчилал, Өмнөд Хойд Солонгосын эвлэрэлд оруулсан хувь нэмрээрээ 2000 онд Нобелийн энх тайвны шагнал хүртсэн.' },
  q285: { q: 'Сөллаль (Солонгос шинэ жил)-ын өглөө идэж, "нэг нас нэмлээ" гэж ярьдаг хоол юу вэ?', explain: 'Сөллалиар солонгосчууд будааны бялуутай шөл буюу ттоггүг (떡국) идэж, нэг нас нэмлээ гэж ярьдаг.' },
  q286: { q: 'Хүүхдийн төрснөөс хойших анхны төрсөн өдрийг юу гэж нэрлэдэг вэ?', explain: 'Хүүхдийн анхны төрсөн өдрийг тол (돌) гэдэг бөгөөд толжанчи хэмээх найр хийдэг.' },
  q287: { q: 'Толын найран дээр хүүхдэд утас, харандаа, мөнгө зэргээс нэгийг бариулж ирээдүйг нь мэргэлдэг заншил юу вэ?', explain: 'Толжаби (돌잡이) ёслолоор хүүхдийн барьсан зүйлээр ирээдүйг нь мэргэлдэг.' },
  q288: { q: 'Сөллаль эсвэл Чусогийн өглөө өвөг дээдэстээ хоол засаж өргөдөг ёслол юу вэ?', explain: 'Баярын өглөө өвөг дээдэстээ өргөдөг ёслолыг чарэ (차례) гэдэг.' },
  q289: { q: 'Нас барсан өвөг дээдсээ дурсан, нас барсан өдөр нь хийдэг ёслол юу вэ?', explain: 'Өвөг дээдсийн нас барсан өдөр хийдэг ёслолыг жэса (제사) гэдэг.' },
  q290: { q: 'Баяраар өвөг дээдсийн булшинд очиж мэндэлж, арчилдаг үйлийг юу гэдэг вэ?', explain: 'Өвөг дээдсийн булшинд очиж арчилж, мэндлэхийг сонмё (성묘) гэдэг.' },
  q291: { q: 'Жилийн хамгийн урт шөнөтэй өвлийн туйлын өдөр иддэг уламжлалт хоол юу вэ?', explain: 'Өвлийн туйлын өдөр солонгосчууд улаан буурцагны зутан буюу пхатжүг (팥죽) идэж, муу зүйлийг хөөдөг байв.' },
  q292: { q: 'Чусогийн (추석) өөр нэг цэвэр солонгос нэр юу вэ?', explain: 'Чусог нь билгийн тооллын 8-р сарын 15-нд тохиодог бөгөөд Хангави (한가위) гэж бас нэрлэдэг.' },
  q293: { q: 'Солонгост төрсөн өдрийн өглөө ихэвчлэн иддэг шөл юу вэ?', explain: 'Төрсөн өдрөөр далайн байцааны шөл буюу миёггүг (미역국) иддэг заншил нь шинэ төрсөн эхчүүд энэ шөлийг иддэгээс үүдэлтэй.' },
  q294: { q: 'Зуны Бокналь өдөр халууныг даван туулахын тулд иддэг, залуу тахиаг женьшень, наалдамхай будаатай чанасан хоол юу вэ?', explain: 'Бокналь өдөр солонгосчууд биеэ тэнхрүүлэхийн тулд самгетан (삼계탕) их иддэг.' },
  q295: { q: 'Будаан дээр төрөл бүрийн ногоо, мах, гочужан тавьж хольж иддэг хоол юу вэ?', explain: 'Бибимбап (비빔밥) бол будаанд ногоо, гочужан зэргийг нэмж хольж иддэг хоол юм.' },
  q296: { q: 'Улаан чинжүүний нунтаг, наалдамхай будаа, исгэсэн шар буурцгийн нунтаг зэргээр хийсэн улаан, халуун ногоотой уламжлалт амтлагч юу вэ?', explain: 'Гочужан (고추장) бол улаан чинжүүний нунтгаар хийсэн улаан, халуун ногоотой амтлагч юм.' },
  q297: { q: 'Ахмад хүнтэй хамт хооллохдоо баримтлах зөв ёс аль вэ?', explain: 'Ахмад хүн эхлээд халбага савхаа барьсны дараа хоол идэж эхлэх нь ёс юм (어른이 먼저 수저를 든 뒤에 먹는다).' },
  q298: { q: 'Ахмад хүнд юм өгөх эсвэл түүнээс авахдаа зөв хандлага аль вэ?', explain: 'Ахмад хүнд юмыг хоёр гараар өгч, хоёр гараар авах нь ёс юм (두 손으로 드리고 받는다).' },
  q299: { q: '\'나이\' (нас) гэдэг үгийн хүндэтгэлийн хэлбэр юу вэ?', explain: '\'나이\'-ийн хүндэтгэлийн хэлбэр нь ёнсэ (연세) бөгөөд "연세가 어떻게 되세요?" (Та хэдэн настай вэ?) гэж хэрэглэнэ.' },
  q300: { q: '\'자다\' (унтах) гэдэг үгийн хүндэтгэлийн хэлбэр юу вэ?', explain: 'Ахмад хүн унтахыг хүндэтгэн жумусида (주무시다) гэж хэлдэг.' },
  q301: { q: '2023 оны 6-р сараас эхлэн хууль, захиргааны ажилд насыг тоолохдоо ямар насыг зарчим болгон ашигладаг вэ?', explain: '2023 оны 6-р сараас хууль, захиргаанд төрсөн өдрөөс тоолдог бүтэн насыг (만 나이) зарчим болгон ашиглаж байна.' },
  q302: { q: 'Төрсөн оныг хулгана, үхэр, бар зэрэг арван хоёр амьтнаар илэрхийлэхийг юу гэдэг вэ?', explain: 'Солонгост төрсөн оныг 12 амьтны жилээр илэрхийлдэг бөгөөд үүнийг тти (띠) гэдэг.' },
  q303: { q: 'Бүтэн 60 нас хүрч буй төрсөн өдрийг юу гэдэг вэ?', explain: 'Бүтэн 60 насны төрсөн өдрийг хуангаб (환갑) гэдэг бөгөөд эрт дээр үед том найр хийдэг байв.' },
  q304: { q: 'Нэг дуучин бөмбөрчний хэмнэлд тааруулан дуу, үг, хөдөлгөөнөөр урт түүх өгүүлдэг уламжлалт урлаг юу вэ?', explain: 'Пансори (판소리) бол дуучин, бөмбөрчин хамтран тоглодог уламжлалт урлаг бөгөөд ЮНЕСКО-гийн Хүн төрөлхтний биет бус соёлын өв юм.' },
  q305: { q: 'Квэнгвари, жин, жангу, бүг гэсэн дөрвөн хөгжмийн зэмсгээр тоглодог уламжлалт хөгжим юу вэ?', explain: 'Самульнори (사물놀이) бол дөрвөн цохиур хөгжмийн зэмсгээр тоглодог хөгжилтэй уламжлалт хөгжим юм.' },
  q306: { q: 'Нутаг бүрт янз бүрийн хэлбэрээр уламжлагдсан, Солонгосыг төлөөлөх ардын дуу юу вэ?', explain: 'Ариран (아리랑) бол Солонгосыг төлөөлөх ардын дуу бөгөөд ЮНЕСКО-гийн Хүн төрөлхтний биет бус соёлын өв юм.' },
  q307: { q: 'Баг зүүж бүжиглэн, дуу, яриагаар язгууртан (янбан)-ыг шоглодог байсан уламжлалт тоглолт юу вэ?', explain: 'Тальчүм (탈춤) бол баг зүүж тоглодог уламжлалт урлаг бөгөөд 2022 онд ЮНЕСКО-гийн биет бус соёлын өвд бүртгэгдсэн.' },
  q308: { q: 'Чусогийн шөнө эмэгтэйчүүд гар гараасаа хөтлөлцөн дугуйлан эргэж, дуулж бүжиглэдэг уламжлалт тоглоом юу вэ?', explain: 'Гангансуллэ (강강술래) бол Чусогийн шөнө тэргэл сарны доор тоглодог уламжлалт тоглоом бөгөөд ЮНЕСКО-гийн биет бус соёлын өв юм.' },
  q309: { q: 'Жусоны үеийн ван, хатдын сүнсний самбарыг залж, тахилга өргөдөг байсан, ЮНЕСКО-гийн Дэлхийн өвд бүртгэгдсэн газар аль вэ?', explain: 'Жунмё (종묘) бол Жусоны хааны гэр бүлийн өвөг дээдсийн сүм бөгөөд 1995 онд ЮНЕСКО-гийн Дэлхийн өвд бүртгэгдсэн.' },
  q310: { q: 'Жусоны Жунжо ван Сувон хотод бариулсан, ЮНЕСКО-гийн Дэлхийн өвд бүртгэгдсэн цайз аль вэ?', explain: 'Сувон Хвасон цайз (수원 화성) Жунжо вангийн үед баригдсан бөгөөд 1997 онд ЮНЕСКО-гийн Дэлхийн өв болсон.' },
  q311: { q: 'Сөүл хотын орднуудаас ЮНЕСКО-гийн Дэлхийн өвд бүртгэгдсэн нь аль вэ?', explain: 'Чандогүн орд (창덕궁) байгальтайгаа зохицсон бөгөөд 1997 онд ЮНЕСКО-гийн Дэлхийн өв болсон.' },
  q312: { q: 'Жусоны үеийн вангуудын төр барьсан үйл хэргийг он сар өдрийн дарааллаар тэмдэглэсэн, ЮНЕСКО-гийн Дэлхийн баримтат өвд бүртгэгдсэн ном аль вэ?', explain: 'Жусон улсын хаадын судар (조선왕조실록) нь Жусоны вангуудын үйл хэргийг тэмдэглэсэн түүхэн ном бөгөөд 1997 онд ЮНЕСКО-гийн Дэлхийн баримтат өвд бүртгэгдсэн.' },
  q313: { q: 'Солонгосын олон ангит кино, кино, поп хөгжим зэрэг дэлхий даяар алдаршиж буй үзэгдлийг юу гэдэг вэ?', explain: 'Солонгосын олон нийтийн соёл дэлхий даяар алдаршиж буй үзэгдлийг Халлю (한류) буюу Солонгосын давалгаа гэдэг.' },
  q314: { q: '2002 онд Солонгос, Япон хамтран зохион байгуулсан олон улсын спортын тэмцээн юу вэ?', explain: '2002 оны Солонгос-Японы хөлбөмбөгийн дэлхийн аварга шалгаруулах тэмцээнд (월드컵) Солонгос шилдэг дөрөвт шалгарсан.' },
  q315: { q: '2018 онд Канвон мужийн Пёнчан хотод болсон олон улсын спортын тэмцээн юу вэ?', explain: '2018 оны Пёнчаны Өвлийн олимп (동계 올림픽) бол Солонгост анх удаа болсон өвлийн олимп юм.' },
  q316: { q: '2024 онд Солонгосчуудаас анх удаа Нобелийн уран зохиолын шагнал хүртсэн зохиолч хэн бэ?', explain: 'Зохиолч Хан Ган (한강) 2024 онд Солонгосчуудаас анх удаа Нобелийн уран зохиолын шагнал хүртсэн.' },
  q317: { q: '1960-аад оноос эхлэн засгийн газар эдийн засгийг хөгжүүлэхийн тулд 5 жилээр төлөвлөн хэрэгжүүлсэн төлөвлөгөө юу вэ?', explain: 'Засгийн газар 1962 оноос эдийн засгийн хөгжлийн 5 жилийн төлөвлөгөө (경제 개발 5개년 계획) хэрэгжүүлж өсөлтийг удирдсан.' },
  q318: { q: '1970-аад онд засгийн газар онцгойлон хөгжүүлсэн ган, усан онгоцны үйлдвэрлэл, химийн зэрэг салбарыг юу гэж нэрлэдэг вэ?', explain: '1970-аад онд ган, усан онгоц, нефть химийн зэрэг хүнд ба химийн үйлдвэрлэл (중화학 공업)-ийг хөгжүүлсэн.' },
  q319: { q: '1997 оны валютын хямралыг даван туулахын тулд ард түмэн хамтран оролцсон хөдөлгөөн юу вэ?', explain: 'Ард иргэд гэртээ байсан алтаа хандивлаж, алт цуглуулах хөдөлгөөн (금 모으기 운동)-өөр улсдаа тусалсан.' },
  q320: { q: '1997 оны валютын хямралын үеэр Солонгост яаралтай зээл олгосон олон улсын байгууллага аль вэ?', explain: 'Солонгос Олон улсын валютын сан (국제통화기금, IMF)-гийн дэмжлэг авсан тул энэ хямралыг "IMF хямрал" гэж бас нэрлэдэг.' },
  q321: { q: 'Солонгос 1996 онд элссэн, ихэвчлэн хөгжингүй орнуудаас бүрдсэн эдийн засгийн хамтын ажиллагааны байгууллага юу вэ?', explain: 'Солонгос 1996 онд Эдийн засгийн хамтын ажиллагаа, хөгжлийн байгууллага (경제협력개발기구, OECD)-д элссэн.' },
  q322: { q: 'Байгалийн баялаг багатай Солонгосын эдийн засгийн онцлогийн талаар зөв нь аль вэ?', explain: 'Солонгос түүхий эд импортлон бүтээгдэхүүн хийж экспортолдог худалдаанд суурилсан эдийн засагтай (수출과 무역의 비중이 크다).' },
  q323: { q: 'Солонгос бараг бүгдийг нь гадаадаас импортолдог эрчим хүчний нөөц юу вэ?', explain: 'Солонгост газрын тос бараг гардаггүй тул түүхий нефть (원유)-ийн ихэнхийг импортолдог.' },
  q324: { q: 'Улс орнууд гаалийн татварыг бууруулах буюу халж, худалдааг чөлөөтэй болгохоор байгуулдаг хэлэлцээр юу вэ?', explain: 'Чөлөөт худалдааны хэлэлцээр (자유 무역 협정, FTA) нь улс хоорондын гаалийн татварыг бууруулж худалдааг нэмэгдүүлэх тохиролцоо юм.' },
  q325: { q: 'Компьютер, ухаалаг гар утсанд заавал ордог бөгөөд Солонгосын хамгийн чухал экспортын бүтээгдэхүүний нэг нь юу вэ?', explain: 'Хагас дамжуулагч (반도체) бол Солонгос дэлхийд тэргүүлдэг гол экспортын салбар юм.' },
  q326: { q: 'Том хөлөг онгоц үйлдвэрлэдэг, Солонгос дэлхийн хэмжээнд өрсөлдөх чадвартай салбар юу вэ?', explain: 'Усан онгоцны үйлдвэрлэл (조선업) нь хөлөг онгоц бүтээх салбар бөгөөд Солонгос энэ чиглэлээр дэлхийд тэргүүлдэг.' },
  q327: { q: 'Автомашин, усан онгоц, нефть химийн үйлдвэрлэл хөгжсөн Солонгосын төлөөлөх аж үйлдвэрийн хот аль вэ?', explain: 'Ульсан (울산) бол автомашин, усан онгоц, нефть химийн үйлдвэрүүд төвлөрсөн аж үйлдвэрийн хот юм.' },
  q328: { q: 'Том ган хайлуулах үйлдвэртэй, ган үйлдвэрлэлээрээ алдартай зүүн эргийн хот аль вэ?', explain: 'Пхохан (포항)-д том ган хайлуулах үйлдвэр байдаг тул ган үйлдвэрлэл хөгжсөн.' },
  q329: { q: 'Ульсан, Асан, Кванжу зэрэг хотын том үйлдвэрт хийгдэж олон оронд экспортлогддог Солонгосын гол аж үйлдвэрийн бүтээгдэхүүн юу вэ?', explain: 'Автомашин (자동차) нь хагас дамжуулагч, хөлөг онгоцны хамт Солонгосын гол экспортын бүтээгдэхүүн юм.' },
  q330: { q: 'Дараахаас аль нь Солонгосын гол экспортын бүтээгдэхүүн биш вэ?', explain: 'Кофены үр (커피 원두) Солонгост бараг ургадаггүй тул импортын бараа юм.' },
  q331: { q: 'Солонгосын эдийн засгийн тогтолцоо юу вэ?', explain: 'Солонгос хувь хүн, аж ахуйн нэгжийн эдийн засгийн эрх чөлөөг хүндэтгэдэг зах зээлийн эдийн засгийн (시장 경제) тогтолцоотой.' },
  q332: { q: 'Зах зээлийн эдийн засагт барааны үнэ гол төлөв юугаар тогтдог вэ?', explain: 'Зах зээл дээр үнэ эрэлт ба нийлүүлэлтээр (수요와 공급) тогтдог.' },
  q333: { q: 'Ямар нэг барааг авах хүн олон боловч бараа хомс бол үнэ ихэвчлэн яадаг вэ?', explain: 'Эрэлт нийлүүлэлтээс их байвал үнэ өснө (오른다).' },
  q334: { q: 'Барааны үнэ тасралтгүй өсөх үзэгдлийг юу гэж нэрлэдэг вэ?', explain: 'Үнэ тасралтгүй өсөхийг инфляци (인플레이션) гэнэ.' },
  q335: { q: 'Компаниуд шударга өрсөлдөж байгаа эсэхийг хянадаг төрийн байгууллага аль вэ?', explain: 'Шударга худалдааны хороо (공정거래위원회) компаниудын шударга бус наймаа, үнийн хуйвалдааныг таслан зогсоодог.' },
  q336: { q: 'Өөрийн улсын мөнгийг гадаад мөнгөөр солих харьцааг юу гэж нэрлэдэг вэ?', explain: 'Валютын ханш (환율) нь воныг гадаад мөнгөөр солих харьцаа бөгөөд өдөр бүр өөрчлөгддөг.' },
  q337: { q: 'Ажиллаж олсон мөнгө (орлого)-ноос төлдөг татвар юу вэ?', explain: 'Орлоготой хүн орлогын албан татвар (소득세) төлдөг.' },
  q338: { q: 'Бараа худалдан авах буюу үйлчилгээ авахад үнэд нь багтаж хамт төлөгддөг татвар юу вэ?', explain: 'Нэмэгдсэн өртгийн албан татвар (부가가치세) барааны үнэд багтдаг бөгөөд хэрэглэгч төлдөг.' },
  q339: { q: 'Гадаадаас бараа оруулж ирэхэд ногдуулдаг татвар юу вэ?', explain: 'Импортын бараанд гаалийн татвар (관세) ногддог.' },
  q340: { q: 'Улсад төлдөг татварыг (улсын татвар) хурааж, удирддаг төв захиргааны байгууллага аль вэ?', explain: 'Үндэсний татварын алба (국세청) орлогын татвар, НӨАТ зэрэг улсын татварыг хураадаг.' },
  q341: { q: 'Ажилтан нэг жилийн турш төлсөн татвараа дахин тооцож, илүү төлснөө буцааж авах, дутуу төлснөө нэмж төлөхийг юу гэдэг вэ?', explain: 'Жилийн эцсийн татварын тооцоо (연말정산) нь нэг жилийн татварыг дахин тооцох журам юм.' },
  q342: { q: 'Дараахаас аль нь Солонгосын нийгмийн 4 даатгалд хамаарахгүй вэ?', explain: 'Нийгмийн 4 даатгал нь үндэсний тэтгэвэр, эрүүл мэнд, ажилгүйдэл, үйлдвэрлэлийн ослын даатгал; аяллын даатгал (여행자 보험) бол хувийн даатгал.' },
  q343: { q: 'Ажил дээрээ гэмтэх эсвэл ажлаасаа болж өвчлөхөд нөхөн төлбөр олгодог даатгал аль вэ?', explain: 'Үйлдвэрлэлийн ослын даатгал (산재보험) ажил дээрээ гэмтсэн, өвчилсөн ажилтныг хамгаалдаг.' },
  q344: { q: 'Ажлаасаа гарсны дараа шинэ ажил хайх хугацаандаа ажилгүйдлийн тэтгэмж авах боломж олгодог даатгал аль вэ?', explain: 'Ажилгүйдлийн даатгалд (고용보험) хамрагдсан хүн нөхцөл хангавал ажилгүйдлийн тэтгэмж авч болно.' },
  q345: { q: 'Үйлдвэрлэлийн ослын даатгалын (산재보험) шимтгэлийг хэн төлдөг вэ?', explain: 'Үйлдвэрлэлийн ослын даатгалын шимтгэлийг ажил олгогч бүтнээр нь төлдөг (사업주가 모두 낸다).' },
  q346: { q: 'Байгууллагад ажилладаг хүний эрүүл мэндийн даатгалын шимтгэлийг ихэвчлэн хэн төлдөг вэ?', explain: 'Ажилтны эрүүл мэндийн даатгалын шимтгэлийг байгууллага ба ажилтан тал талаас нь төлдөг (회사와 근로자가 반씩 낸다).' },
  q347: { q: 'Эрүүл мэндийн даатгалын шимтгэл хурааж, улсын эрүүл мэндийн үзлэгийн талаар мэдээлдэг төрийн байгууллага аль вэ?', explain: 'Үндэсний эрүүл мэндийн даатгалын корпораци (국민건강보험공단) эрүүл мэндийн даатгал, үзлэгийн ажлыг хариуцдаг.' },
  q348: { q: 'Ажил дээрээ гэмтсэн үед үйлдвэрлэлийн ослын даатгалын тэтгэмжийг аль төрийн байгууллагад хүсэлт гаргаж авдаг вэ?', explain: 'Үйлдвэрлэлийн ослын даатгалын тэтгэмжийг Хөдөлмөрийн халамжийн корпорацид (근로복지공단) хүсэлт гаргаж авдаг.' },
  q349: { q: 'Үндэсний тэтгэврийн даатгуулагч нас барахад түүний гэр бүл авдаг тэтгэвэр юу вэ?', explain: 'Даатгуулагч нас барвал үлдсэн гэр бүл нь тэжээгчээ алдсаны тэтгэвэр (유족연금) авч болно.' },
  q350: { q: 'Амьжиргаа хүнд хүмүүст амьжиргааны болон эмчилгээний зардлыг дэмжиж, хамгийн бага амьжиргааг баталгаажуулдаг тогтолцоо юу вэ?', explain: 'Үндэсний үндсэн амьжиргааг баталгаажуулах тогтолцоогоор (국민기초생활보장 제도) төр хүнд байдалтай хүмүүсийн үндсэн амьжиргааг дэмждэг.' },
  q351: { q: 'Орлого багатай ахмад настанд төрөөс сар бүр олгодог тэтгэвэр юу вэ?', explain: 'Үндсэн тэтгэвэр (기초연금) нь амьжиргаа хүнд ахмадуудад төрөөс олгодог тэтгэвэр юм.' },
  q352: { q: 'Өндөр нас эсвэл өндөр насны өвчнөөс болж ганцаараа амьдрахад хэцүү хүмүүст асаргааны үйлчилгээ үзүүлдэг даатгал аль вэ?', explain: 'Ахмад настны урт хугацааны асаргааны даатгал (노인장기요양보험) гэрт нь очиж асрах зэрэг үйлчилгээ үзүүлдэг.' },
  q353: { q: 'Хүүхэд өсгөж буй гэр бүлд төрөөс сар бүр олгодог мөнгө юу вэ?', explain: 'Хүүхдийн мөнгө (아동수당) нь хүүхэд өсгөх ачааллыг хөнгөлөх зорилгоор төрөөс олгодог.' },
  q354: { q: 'Бага насны хүүхдээ асрахын тулд тодорхой хугацаанд ажлаасаа чөлөө авах боломжтой тогтолцоо юу вэ?', explain: 'Хүүхэд асрах чөлөө (육아 휴직) нь хүүхдээ асрахын тулд тодорхой хугацаанд ажлаас чөлөө авах тогтолцоо бөгөөд ээж, аав хоёулаа авч болно.' },
  q355: { q: 'Банкинд мөнгө хадгалуулахад банкнаас түүний хариуд өгдөг мөнгө юу вэ?', explain: 'Банкинд хадгаламж хийвэл хүү (이자) авна.' },
  q356: { q: 'Сар бүр тогтмол мөнгө хийж их хэмжээний мөнгө хуримтлуулдаг банкны бүтээгдэхүүн юу вэ?', explain: 'Хуримтлалын хадгаламжид (적금) сар бүр мөнгө хийж, хугацаа дуусахад хүүгийн хамт авдаг.' },
  q357: { q: 'Банкнаас мөнгө зээлэхийг юу гэж нэрлэдэг вэ?', explain: 'Банкнаас мөнгө зээлэхийг зээл (대출) гэх бөгөөд хүүтэй нь буцааж төлөх ёстой.' },
  q358: { q: 'Солонгос мөнгийг доллар зэрэг гадаад мөнгөөр солихыг юу гэж нэрлэдэг вэ?', explain: 'Мөнгийг өөр улсын мөнгөөр солихыг валют солих (환전) гэнэ.' },
  q359: { q: '50,000 воны дэвсгэрт дээрх хүн хэн бэ?', explain: '50,000 воны дэвсгэрт дээр Жусон улсын үеийн уран бүтээлч Шин Саимдан (신사임당) байдаг.' },
  q360: { q: 'Барааны төлбөр төлөхөд өөрийн дансаас мөнгө шууд хасагддаг карт аль вэ?', explain: 'Дебит карт (체크카드) дансаас шууд хасдаг бол кредит картаар дараа нь төлдөг.' },
  q361: { q: 'Банк дампуурсан ч хуулиар тогтоосон хэмжээ хүртэлх хадгаламжийг буцааж олгодог тогтолцоо юу вэ?', explain: 'Хадгаламж эзэмшигчийг хамгаалах тогтолцоо (예금자 보호 제도) банк дампуурсан ч тодорхой хэмжээ хүртэл хадгаламжийг хамгаалдаг.' },
  q362: { q: 'Прокурор эсвэл банкны ажилтан мэт хууран утсаар мөнгө шилжүүлэхийг шаарддаг залилан юу вэ?', explain: 'Утасны залилан (보이스피싱) гэж сэжиглэвэл мөнгө бүү шилжүүл, 112-т мэдэгдээрэй.' },
  q363: { q: 'Бараа, үйлчилгээ хэрэглээд хохирол амссан үед зөвлөгөө, тусламж авч болох байгууллага аль вэ?', explain: 'Солонгосын хэрэглэгчдийн агентлаг (한국소비자원) хэрэглэгчийн хохирлын талаар зөвлөгөө өгч шийдвэрлэхэд тусалдаг.' },
  q364: { q: 'Интернэтээр худалдаж авсан барааг зарчмын хувьд хүлээн авснаас хойш хэдэн хоногийн дотор буцааж болох вэ?', explain: 'Интернэтээр авсан барааг зарчмын хувьд хүлээн авснаас хойш 7 хоногийн (7일) дотор буцааж болно.' },
  q365: { q: 'Байрны эзэнд их хэмжээний барьцаа мөнгө тушааж, сар бүрийн түрээс төлдөггүй Солонгосын орон сууц түрээслэх хэлбэр юу вэ?', explain: 'Жонсэ (전세) нь барьцаа мөнгө тушааж амьдраад гэрээ дуусахад буцааж авдаг хэлбэр юм.' },
  q366: { q: '1-ээс дээш жил ажилласан ажилтан ажлаасаа гарахад компаниас өгдөг мөнгө юу вэ?', explain: '1-ээс дээш жил тасралтгүй ажилласан ажилтан ажлаас гарахдаа ажлаас гарсны тэтгэмж (퇴직금) авна.' },
  q367: { q: 'Гадаад ажилчдыг Солонгосын компанид хууль ёсоор ажиллуулахыг засгийн газраас зөвшөөрдөг тогтолцоо юу вэ?', explain: 'Ажил эрхлэлтийн зөвшөөрлийн тогтолцоо (고용허가제) нь ажиллах хүч дутагдсан компани засгийн газрын зөвшөөрлөөр гадаад ажилтан ажиллуулах тогтолцоо юм.' },
  q368: { q: 'Ажиллах чадвар, хүсэлтэй боловч ажил олж чадахгүй байгаа байдлыг юу гэж нэрлэдэг вэ?', explain: 'Ажиллахыг хүссэн ч ажилгүй байх байдлыг ажилгүйдэл (실업) гэнэ.' },
  q369: { q: 'Бүгд Найрамдах Солонгос Улс аль тивийн зүүн хэсэгт оршдог вэ?', explain: 'Солонгос Ази (아시아) тивийн зүүн хэсэгт, Солонгосын хойгт оршдог.' },
  q370: { q: 'Зүүн тэнгисийг (동해) дундаа зааглан Солонгосын зүүн талд орших хөрш улс аль вэ?', explain: 'Япон (일본) бол Зүүн тэнгисийн цаана Солонгосын зүүн талд орших хөрш улс юм.' },
  q371: { q: 'Солонгосын хойгийн хойд хилийг үүсгэдэг хоёр гол юу вэ?', explain: 'Солонгосын хойгийн хойд хэсэг Ялу ба Түмэн голоор (압록강과 두만강) Хятад, Оростой хиллэдэг.' },
  q372: { q: 'Галын хоригийн шугамыг даган өмнөд, хойд хоёр талд цэрэг байршуулахгүй байхаар тохирсон бүсийг юу гэж нэрлэдэг вэ?', explain: 'Галын хоригийн шугамын орчмын цэрэггүй бүсийг цэрэггүй бүс (비무장 지대, DMZ) гэнэ.' },
  q373: { q: 'Цэрэггүй бүс (DMZ) цэргийн зааг шугамаас урагш, хойш тус бүр хэдэн км вэ?', explain: 'Цэрэггүй бүс зааг шугамаас тал бүр тийш 2 км (2km), нийт өргөн нь 4 км орчим.' },
  q374: { q: 'Цэргийн зааг шугам дээр байрлах, хамтарсан хамгаалалтын бүстэй, хоёр Солонгосын хэлэлцээ ч болж байсан газар хаана вэ?', explain: 'Пханмунжомд (판문점) хамтарсан хамгаалалтын бүс (JSA) байдаг бөгөөд хоёр Солонгосын хэлэлцээ болж байсан.' },
  q375: { q: 'Удаан хугацаанд хүн нэвтрэхийг хязгаарласан цэрэггүй бүс өнөөдөр ямар газар болж анхаарал татаж байна вэ?', explain: 'Хүний хөл хүрээгүй тул цэрэггүй бүс байгалийн экосистем сайн хадгалагдсан газар (자연 생태계가 잘 보존된 곳) болсон.' },
  q376: { q: 'Үндсэн хуульд заасан Бүгд Найрамдах Солонгос Улсын нутаг дэвсгэр хаана вэ?', explain: 'Үндсэн хуулийн 3-р зүйлд нутаг дэвсгэрийг Солонгосын хойг ба түүний харьяа арлууд (한반도와 그 부속 도서) гэж заасан.' },
  q377: { q: 'Солонгосын нутаг дэвсгэрийн 70 орчим хувийг эзэлдэг газрын хэлбэр юу вэ?', explain: 'Солонгосын нутгийн 70 орчим хувь нь уулархаг газар (산지) юм.' },
  q378: { q: 'Солонгосын газрын гадаргын онцлогийн талаар зөв нь аль вэ?', explain: 'Солонгосын зүүн хэсэгт өндөр уул олон, баруун тийшээ намсдаг (동쪽이 높고 서쪽이 낮다).' },
  q379: { q: 'Бэгдү уулаас Жири уул хүртэл Солонгосын хойгийг хойноос урагш холбосон том нурууг юу гэж нэрлэдэг вэ?', explain: 'Бэгдүдэган (백두대간) бол Солонгосын хойгийн нуруу мэт том уулын нуруу юм.' },
  q380: { q: 'Сорак уул аль мужид байдаг вэ?', explain: 'Сорак уул Канвон тусгай өөрөө удирдах мужийн (강원특별자치도) зүүн хэсэгт байдаг.' },
  q381: { q: 'Солонгосын анхны үндэсний цэцэрлэгт хүрээлэнгээр тогтоогдсон уул аль вэ?', explain: 'Жири уул (지리산) 1967 онд Солонгосын анхны үндэсний цэцэрлэгт хүрээлэн болсон.' },
  q382: { q: 'Өмнөд Солонгосын хамгийн урт гол аль вэ?', explain: 'Нагдун гол (낙동강) Өмнөд Солонгосын хамгийн урт гол бөгөөд Өмнөд тэнгис рүү цутгадаг.' },
  q383: { q: 'Будаа их ургадаг, Солонгосын хамгийн өргөн тал аль вэ?', explain: 'Хонам тал (호남평야) бол Солонгосын хамгийн өргөн тал бөгөөд будаа тариалалт хөгжсөн.' },
  q384: { q: 'Жэжү арал юунаас үүссэн арал вэ?', explain: 'Жэжү бол галт уулын үйл ажиллагааны (화산 활동) үр дүнд үүссэн галт уулын арал юм.' },
  q385: { q: 'Докдог бүрдүүлдэг хоёр том арал юу вэ?', explain: 'Докдо нь Зүүн арал ба Баруун арал (동도와 서도), мөн эргэн тойрны жижиг хадан арлуудаас бүрддэг.' },
  q386: { q: 'Докдод хамгийн ойр орших Солонгосын том арал аль вэ?', explain: 'Уллөн арал (울릉도) Зүүн тэнгист оршдог бөгөөд Докдод хамгийн ойр.' },
  q387: { q: 'Солонгосын хамгийн том арал аль вэ?', explain: 'Жэжү арал (제주도) Солонгосын хамгийн том арал бөгөөд Жэжү тусгай өөрөө удирдах мужид хамаардаг.' },
  q388: { q: 'Солонгосын уур амьсгалын онцлогийн талаар зөв нь аль вэ?', explain: 'Солонгост хавар, зун, намар, өвөл гэсэн дөрвөн улирал тод ялгардаг (사계절이 뚜렷하다).' },
  q389: { q: 'Өвөл Солонгос руу хүйтэн, хуурай салхи голдуу аль зүгээс салхилдаг вэ?', explain: 'Өвөл эх газраас баруун хойд зүгийн (북서쪽) улирлын салхи салхилж хүйтэн, хуурай байдаг.' },
  q390: { q: 'Зунаас намрын эхэн хүртэлх хугацаанд хүчтэй салхи, их бороо авчирдаг зүйл юу вэ?', explain: 'Тайфун (태풍) зун ба намрын эхэнд хүчтэй салхи, их бороо авчирдаг.' },
  q391: { q: 'Хавар Хятад, Монголын цөлөөс хийсэж ирдэг шар тоос шороо юу вэ?', explain: 'Хавар цөлөөс хийсэж ирдэг шар тоосыг шар шороо (황사) гэнэ.' },
  q392: { q: 'Өвлийн цаг агаарыг "гурван өдөр хүйтэн, дөрвөн өдөр дулаан" гэсэн утгаар илэрхийлдэг үг юу вэ?', explain: 'Самхансаон (삼한사온) нь өвөл хүйтэн, дулаан өдрүүд ээлжлэн солигдох үзэгдэл юм.' },
  q393: { q: 'Зүүн тэнгисийн (동해) онцлогийн талаар зөв нь аль вэ?', explain: 'Зүүн тэнгис гүн бөгөөд эргийн шугам нь харьцангуй жигд (물이 깊고 해안선이 단조롭다).' },
  q394: { q: 'Солонгосын тэнгисүүдээс аль нь түрлэг татлагын зөрүү хамгийн их, далайн шавар эрэг өргөн тархсан бэ?', explain: 'Баруун тэнгис (서해) гүехэн, түрлэг татлагын зөрүү их тул далайн шавар эрэг өргөн.' },
  q395: { q: 'Нийслэл Сөүлийн засаг захиргааны албан ёсны нэр юу вэ?', explain: 'Сөүлийн албан ёсны нэр нь Сөүл тусгай хот (서울특별시) юм.' },
  q396: { q: 'Олон төв захиргааны байгууллага нүүн шилжиж, засаг захиргааны төв хот болгон байгуулсан газар хаана вэ?', explain: 'Сэжун тусгай өөрөө удирдах хотод (세종특별자치시) засгийн газрын цогцолбор байрлаж, олон яам ажилладаг.' },
  q397: { q: 'Пусан, Инчхон зэрэг мужид харьяалагддаггүй том хотуудад өгдөг засаг захиргааны нэгжийн нэр юу вэ?', explain: 'Пусан, Инчхон зэрэг том хотууд мужтай ижил түвшний томоохон хот (광역시) юм.' },
  q398: { q: '2024 оноос Хойд Чолла мужийн (전라북도) оронд хэрэглэж буй албан ёсны нэр юу вэ?', explain: 'Хойд Чолла муж 2024 оны 1-р сард Чонбук тусгай өөрөө удирдах муж (전북특별자치도) болсон.' },
  q399: { q: 'Сөүл, Инчхон, Кёнги мужийг хамтад нь юу гэж нэрлэдэг вэ?', explain: 'Сөүл, Инчхон, Кёнгиг нийслэлийн бүс (수도권) гэх бөгөөд хүн амын тал орчим нь амьдардаг.' },
  q400: { q: 'Солонгосын хамгийн том олон улсын нисэх онгоцны буудал аль хотод байдаг вэ?', explain: 'Инчхон (인천) олон улсын нисэх онгоцны буудал нь Солонгосын хамгийн том олон улсын нисэх буудал юм.' },
}
